    function ensureLorebookStore() {
        const store = getStore();
        if (!Array.isArray(store.lorebookSources)) store.lorebookSources = [];
        return store.lorebookSources;
    }

    function inferLorebookType(name) {
        const text = String(name || '').toLowerCase();
        if (text.includes('主体') || text.includes('文生图')) return 'main';
        if (text.includes('标签库')) return 'taglib';
        if (text.includes('sex')) return 'sex';
        if (text.includes('模板')) return 'template';
        return 'custom';
    }

    function getSillyTavernHeaders() {
        let headers = {};
        const getHeaders = window.RBQ?.api?.getStRequestHeaders || window.RBQ?.api?.getRequestHeaders;
        if (typeof getHeaders === 'function') {
            try { Object.assign(headers, getHeaders()); } catch (_e) {}
        }
        if (typeof window.getRequestHeaders === 'function') {
            try { Object.assign(headers, window.getRequestHeaders()); } catch (_e) {}
        }
        const ctx = (window.RBQ?.api?.getContext?.()) || (window.SillyTavern?.getContext?.());
        if (typeof ctx?.getRequestHeaders === 'function') {
            try { Object.assign(headers, ctx.getRequestHeaders()); } catch (_e) {}
        }
        return {
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest',
            ...headers,
        };
    }

    function getSTWorldNames() {
        const ctx = (window.RBQ?.api?.getContext?.()) || (window.SillyTavern?.getContext?.());
        if (Array.isArray(ctx?.world_names) && ctx.world_names.length > 0) {
            return ctx.world_names;
        }
        if (Array.isArray(window.world_names) && window.world_names.length > 0) {
            return window.world_names;
        }
        return [];
    }

    async function loadWorldInfoFromST(worldName) {
        if (!worldName) return null;
        const cleanName = String(worldName).replace(/\.json$/i, '').trim();
        const ctx = (window.RBQ?.api?.getContext?.()) || (window.SillyTavern?.getContext?.());
        if (typeof ctx?.loadWorldInfo === 'function') {
            try {
                const data = await ctx.loadWorldInfo(cleanName);
                if (data && (data.entries || typeof data === 'object')) return data;
            } catch (_e) {}
        }
        if (typeof window.loadWorldInfo === 'function') {
            try {
                const data = await window.loadWorldInfo(cleanName);
                if (data && (data.entries || typeof data === 'object')) return data;
            } catch (_e) {}
        }
        // 尝试通过 POST /api/worldinfo/get 读取（注入 X-CSRF-Token 鉴权头）
        try {
            const resp = await fetch('/api/worldinfo/get', {
                method: 'POST',
                headers: getSillyTavernHeaders(),
                body: JSON.stringify({ name: cleanName }),
            });
            if (resp.ok) {
                const data = await resp.json();
                if (data && (data.entries || typeof data === 'object')) return data;
            }
        } catch (e) {
            console.warn(`[${PLUGIN_NAME}] 从酒馆加载世界书 ${cleanName} 失败:`, e);
        }
        // 若无后缀尝试失败，追加 .json 再次尝试
        try {
            const resp = await fetch('/api/worldinfo/get', {
                method: 'POST',
                headers: getSillyTavernHeaders(),
                body: JSON.stringify({ name: `${cleanName}.json` }),
            });
            if (resp.ok) {
                const data = await resp.json();
                if (data && (data.entries || typeof data === 'object')) return data;
            }
        } catch (_e) {}
        return null;
    }

    async function saveWorldInfoToST(worldName, data) {
        if (!worldName || !data) return false;
        const cleanName = String(worldName).replace(/\.json$/i, '').trim();
        const ctx = (window.RBQ?.api?.getContext?.()) || (window.SillyTavern?.getContext?.());
        if (typeof ctx?.saveWorldInfo === 'function') {
            try {
                await ctx.saveWorldInfo(cleanName, data);
                return true;
            } catch (_e) {}
        }
        if (typeof window.saveWorldInfo === 'function') {
            try {
                await window.saveWorldInfo(cleanName, data);
                return true;
            } catch (_e) {}
        }
        try {
            const resp = await fetch('/api/worldinfo/post', {
                method: 'POST',
                headers: getSillyTavernHeaders(),
                body: JSON.stringify({ name: cleanName, data }),
            });
            if (resp.ok) {
                const names = getSTWorldNames();
                if (Array.isArray(names) && !names.includes(cleanName)) {
                    names.push(cleanName);
                }
                return true;
            }
        } catch (e) {
            console.warn(`[${PLUGIN_NAME}] 转存世界书 ${cleanName} 至酒馆失败:`, e);
        }
        return false;
    }

    const SDT_IDB_NAME = 'rbq_sdt_storage';
    const SDT_IDB_STORE = 'lorebooks';
    let sdtIdbPromise = null;

    function getSdtIdb() {
        if (!sdtIdbPromise) {
            sdtIdbPromise = new Promise((resolve) => {
                try {
                    const req = indexedDB.open(SDT_IDB_NAME, 1);
                    req.onupgradeneeded = (e) => {
                        const db = e.target.result;
                        if (!db.objectStoreNames.contains(SDT_IDB_STORE)) {
                            db.createObjectStore(SDT_IDB_STORE, { keyPath: 'id' });
                        }
                    };
                    req.onsuccess = (e) => resolve(e.target.result);
                    req.onerror = () => resolve(null);
                } catch (_e) {
                    resolve(null);
                }
            });
        }
        return sdtIdbPromise;
    }

    async function saveLorebookToIDB(sourceId, entries) {
        if (!sourceId || !Array.isArray(entries)) return;
        try {
            const db = await getSdtIdb();
            if (!db) return;
            const tx = db.transaction(SDT_IDB_STORE, 'readwrite');
            tx.objectStore(SDT_IDB_STORE).put({ id: sourceId, entries, updatedAt: Date.now() });
        } catch (_e) {}
    }

    async function loadLorebookFromIDB(sourceId) {
        if (!sourceId) return null;
        try {
            const db = await getSdtIdb();
            if (!db) return null;
            return new Promise((resolve) => {
                const tx = db.transaction(SDT_IDB_STORE, 'readonly');
                const req = tx.objectStore(SDT_IDB_STORE).get(sourceId);
                req.onsuccess = () => resolve(req.result?.entries || null);
                req.onerror = () => resolve(null);
            });
        } catch (_e) {
            return null;
        }
    }

    function normalizeLorebookSource(raw, fallbackName = '未命名世界书') {
        const entries = raw?.entries && typeof raw.entries === 'object' ? raw.entries : {};
        return {
            id: String(raw?.id || `sdt-lb-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`),
            name: String(raw?.name || fallbackName),
            enabled: raw?.enabled !== false,
            type: String(raw?.type || inferLorebookType(raw?.name || fallbackName)),
            sourcePath: String(raw?.sourcePath || ''),
            importedAt: Number(raw?.importedAt || Date.now()),
            entryCount: raw?.entryCount != null ? Number(raw.entryCount) : Object.keys(entries).length,
            isNativeST: raw?.isNativeST !== false,
        };
    }

    function normalizeLorebookEntry(source, entryKey, entry) {
        const characterFilter = entry?.characterFilter && typeof entry.characterFilter === 'object'
            ? entry.characterFilter
            : {};
        return {
            sourceId: source.id,
            sourceName: source.name,
            sourceType: source.type,
            uid: entry?.uid ?? entryKey,
            comment: String(entry?.comment || ''),
            content: String(entry?.content || '').trim(),
            constant: !!entry?.constant,
            disabled: !!(entry?.disable ?? entry?.disabled),
            key: Array.isArray(entry?.key) ? entry.key.map(k => String(k || '').trim().replace(/^[,，\s]+|[,，\s]+$/g, '')).filter(Boolean) : [],
            keysecondary: Array.isArray(entry?.keysecondary) ? entry.keysecondary.map(k => String(k || '').trim().replace(/^[,，\s]+|[,，\s]+$/g, '')).filter(Boolean) : [],
            order: Number(entry?.order || 0),
            selective: entry?.selective !== false,
            selectiveLogic: Number(entry?.selectiveLogic || 0),
            sticky: Math.max(0, Number(entry?.sticky || 0)),
            cooldown: Math.max(0, Number(entry?.cooldown || 0)),
            depth: entry?.depth == null ? null : Math.max(0, Number(entry.depth) || 0),
            preventRecursion: !!entry?.preventRecursion,
            excludeRecursion: !!entry?.excludeRecursion,
            caseSensitive: !!entry?.caseSensitive,
            matchWholeWords: !!entry?.matchWholeWords,
            probability: Math.max(0, Math.min(100, Number(entry?.probability || 100))),
            useProbability: !!entry?.useProbability,
            group: String(entry?.group || ''),
            groupOverride: !!entry?.groupOverride,
            groupWeight: Math.max(0, Number(entry?.groupWeight || 100)),
            useGroupScoring: !!entry?.useGroupScoring,
            role: entry?.role ?? null,
            characterFilter: {
                isExclude: !!characterFilter.isExclude,
                names: Array.isArray(characterFilter.names) ? characterFilter.names.map(String).filter(Boolean) : [],
                tags: Array.isArray(characterFilter.tags) ? characterFilter.tags.map(String).filter(Boolean) : [],
            },
        };
    }

    function getLorebookEntryRuntimeKey(entry) {
        return `${entry.sourceId}:${entry.uid}`;
    }

    function parseLorebookData(rawOrObj, fallbackName = '未命名世界书', source = null) {
        let parsed = {};
        if (typeof rawOrObj === 'string') {
            try { parsed = JSON.parse(rawOrObj || '{}'); } catch (_e) { parsed = {}; }
        } else if (rawOrObj && typeof rawOrObj === 'object') {
            parsed = rawOrObj;
        }
        const effectiveSource = source || normalizeLorebookSource(parsed, fallbackName);
        const entries = parsed?.entries && typeof parsed.entries === 'object' ? parsed.entries : {};
        const normalizedEntries = Object.entries(entries)
            .map(([entryKey, entry]) => normalizeLorebookEntry(effectiveSource, entryKey, entry))
            .filter((entry) => {
                if (!entry.content) return false;
                const content = entry.content.trim();
                // 过滤纯 markdown 分隔符或空章节标头（如 `### 全局`, `---`），节省无用 Token
                if (/^[-#\s\n\r*`_~]+$/.test(content)) return false;
                return true;
            });
        return {
            source: effectiveSource,
            entries: normalizedEntries,
            rawObj: parsed,
        };
    }

    function parseLorebookRawJson(rawJson, fallbackName = '未命名世界书') {
        return parseLorebookData(rawJson, fallbackName);
    }

    async function warmLorebookMemoryCache(targetSourceId = null, includeDisabled = false) {
        const sources = ensureLorebookStore();
        const promises = [];
        for (const source of sources) {
            if (!source) continue;
            if (targetSourceId && source.id !== targetSourceId) continue;
            if (!targetSourceId && !includeDisabled && source.enabled === false) continue;
            if (lorebookMemoryCache.has(source.id) && lorebookMemoryCache.get(source.id)?.length > 0) continue;

            promises.push((async () => {
                // 1. Try SillyTavern native storage
                let stData = await loadWorldInfoFromST(source.name);
                if (stData) {
                    const parsed = parseLorebookData(stData, source.name, source);
                    if (Array.isArray(parsed?.entries) && parsed.entries.length > 0) {
                        lorebookMemoryCache.set(source.id, parsed.entries);
                        saveLorebookToIDB(source.id, parsed.entries);
                        source.entryCount = parsed.entries.length;
                        return;
                    }
                }
                // 2. Try IndexedDB offline fallback
                let idbEntries = await loadLorebookFromIDB(source.id);
                if (Array.isArray(idbEntries) && idbEntries.length > 0) {
                    lorebookMemoryCache.set(source.id, idbEntries);
                    source.entryCount = idbEntries.length;
                    return;
                }
            })());
        }
        if (promises.length > 0) {
            await Promise.allSettled(promises);
        }
    }

    function getNormalizedLorebooks(requestStore = null) {
        const store = requestStore || getStore();
        if (!store.lorebookEnabled) return [];
        return (requestStore ? requestStore.lorebookSources || [] : ensureLorebookStore())
            .filter((source) => source && source.enabled !== false)
            .flatMap((source) => {
                const cached = lorebookMemoryCache.get(source.id);
                if (Array.isArray(cached)) return cached.filter(e => !e.disabled);
                return [];
            });
    }

    function extractLorebookSubVariants(content) {
        if (!content) return [];
        // Normalize zero-width spaces and special whitespace
        const normalized = content.replace(/[\ufeff\u200b\u200c\u200d]/g, '').trim();
        const lines = normalized.split(/\r?\n/);
        const variants = [];
        let currentTitle = '';
        let currentTags = [];

        function isTagLine(line) {
            if (/\d+(\.\d+)?::/.test(line) || /-\d+::/.test(line)) return true;
            if ((line.match(/,/g) || []).length >= 2) return true;
            const eng = (line.match(/[a-zA-Z_]/g) || []).length;
            const ch = (line.match(/[\u4e00-\u9fa5]/g) || []).length;
            if (eng > 10 && ch === 0) return true;
            return false;
        }

        for (let rawLine of lines) {
            let line = rawLine.trim();
            if (!line) continue;

            if (/^#+\s+[\u4e00-\u9fa5a-zA-Z0-9_\-]+$/.test(line) && !currentTitle && !variants.length) {
                continue;
            }

            const chineseCount = (line.match(/[\u4e00-\u9fa5]/g) || []).length;
            const englishCount = (line.match(/[a-zA-Z]/g) || []).length;
            const isTag = isTagLine(line);

            let isHeader = false;
            if (!isTag) {
                if (line.startsWith('##') || line.startsWith('###')) {
                    isHeader = true;
                } else if (/^[【\[（\(][^】\]）\)]+[】\]）\)]/.test(line) && chineseCount >= 2) {
                    isHeader = true;
                } else if (/^(\d+[\.\、\s]|[-*]\s+)[^\d]/i.test(line) && (chineseCount >= 2 || englishCount < 10)) {
                    isHeader = true;
                } else if (/^(默认\d*|变体\d*|机位\d*|视角\d*|版本\d*|服装\d*|姿势\d*|动作\d*|Char\d*)/i.test(line)) {
                    isHeader = true;
                } else if (chineseCount >= 2 && englishCount <= 6 && !line.includes(',')) {
                    isHeader = true;
                } else if (/^[\u4e00-\u9fa5a-zA-Z0-9_\-\s]+[：:]$/.test(line)) {
                    isHeader = true;
                }
            }

            if (isHeader) {
                if (currentTitle && currentTags.length > 0) {
                    variants.push({ title: currentTitle, tags: currentTags.join(', ').trim() });
                }
                currentTitle = line.replace(/^#+\s*/, '').replace(/^[-*]\s*/, '').replace(/[:：]$/, '').trim();
                currentTags = [];
            } else {
                if (!currentTitle) currentTitle = '默认变体';
                currentTags.push(line.replace(/^[-*]\s*/, ''));
            }
        }
        if (currentTitle && currentTags.length > 0) {
            variants.push({ title: currentTitle, tags: currentTags.join(', ').trim() });
        }
        return variants.length > 0 ? variants : [{ title: '默认', tags: content.trim() }];
    }

