    function utf8ToBase64(str) {
        if (!str) return '';
        try {
            const bytes = new TextEncoder().encode(String(str));
            let binary = '';
            const len = bytes.byteLength;
            for (let i = 0; i < len; i++) {
                binary += String.fromCharCode(bytes[i]);
            }
            return btoa(binary);
        } catch (_e) {
            try {
                return btoa(unescape(encodeURIComponent(String(str))));
            } catch (_e2) {
                return '';
            }
        }
    }

