    function assembleDrawRequestMessagesAndTool(fullSystemPrompt, payload, store, promptBundle = null) {
        const standardRequest = buildStandardDrawRequest(fullSystemPrompt, payload, store, promptBundle);
        if (standardRequest) return standardRequest;

        const isFullContextTool = store?.provider !== 'custom' && store?.toolCallMode && store?.toolInputInDescription;
        if (isFullContextTool) {
            return {
                messages: [
                    { role: 'system', content: getReorganizedSystemPrompt(store) },
                    { role: 'user', content: getReorganizedUserMessage(store) },
                ],
                tool: getDrawSpecTool(store, promptBundle, payload, fullSystemPrompt),
            };
        }

        const jailbreakPrompt = getActiveJailbreakPrompt(store);
        const rawMessages = (store?.geminiJailbreak && jailbreakPrompt)
            ? parseJailbreakMessages(jailbreakPrompt, fullSystemPrompt)
            : [{ role: 'system', content: fullSystemPrompt }];

        const userContent = (store?.geminiJailbreak && (store?.geminiJailbreakPreset === 'render_pipeline_v2' || store?.geminiJailbreakPreset === 'kami_gase'))
            ? wrapPayloadInRenderTelemetryV2(payload)
            : (store?.geminiJailbreak && store?.geminiJailbreakPreset === 'render_pipeline')
            ? wrapPayloadInRenderTelemetry(payload)
            : JSON.stringify(payload, null, 2);
        rawMessages.push({ role: 'user', content: userContent });

        applyPostProcessPrompt(rawMessages, store);

        const messages = store?.squashMessages !== false
            ? squashConsecutiveMessages(rawMessages)
            : rawMessages;

        const tool = store?.toolCallMode
            ? getDrawSpecTool(store, promptBundle, payload)
            : null;

        return { messages, tool };
    }

    function buildThinkingParams(store) {
        if (!store) return {};
        const effort = store.thinkingEffort || 'default';
        if (effort === 'default') return {};

        let budget = 0;
        let reasoning = '';

        if (effort === 'off') {
            budget = 0;
            reasoning = 'none';
        } else if (effort === 'low') {
            budget = 1024;
            reasoning = 'low';
        } else if (effort === 'medium') {
            budget = 4096;
            reasoning = 'medium';
        } else if (effort === 'high') {
            budget = 8192;
            reasoning = 'high';
        } else if (effort === 'custom') {
            budget = Math.max(0, Number(store.thinkingBudget) || 0);
            if (budget === 0) {
                reasoning = 'none';
            } else if (budget <= 1500) {
                reasoning = 'low';
            } else if (budget <= 5000) {
                reasoning = 'medium';
            } else {
                reasoning = 'high';
            }
        }

        const params = {};

        if (reasoning) {
            params.reasoning_effort = reasoning;
        }

        if (budget > 0) {
            params.thinking_budget = budget;
            params.thinking = { type: 'enabled', budget_tokens: budget };
        } else if (effort === 'off' || (effort === 'custom' && budget === 0)) {
            params.thinking_budget = 0;
            params.thinking = { type: 'disabled' };
        }

        return params;
    }

    async function callApiWithJsonFallback(url, fetchOptions, reqBodyObj, customFetch = smartFetch) {
        let currentBody = { ...reqBodyObj };
        let response = await customFetch(url, {
            ...fetchOptions,
            body: JSON.stringify(currentBody),
        });

        const getErrText = async (res) => {
            try {
                return await res.clone().text();
            } catch (_e) {
                return '';
            }
        };

        // 1. 如果报错 400 且含有思维链参数，尝试思维链降级（避免思维链参数阻碍后续 tools/response_format 协商）
        if (!response.ok && response.status === 400 && (currentBody.thinking || currentBody.thinking_budget !== undefined || currentBody.reasoning_effort)) {
            const errText = (await getErrText(response)).toLowerCase();
            const mentionsReasoning = errText.includes('reasoning');
            const mentionsThinking = errText.includes('thinking') || errText.includes('budget');

            if (mentionsReasoning && !mentionsThinking) {
                console.warn(`[${PLUGIN_NAME}] API 报错包含 reasoning 关键字，怀疑端点不支持 reasoning_effort，正在剥离重试...`);
                const retryBody = { ...currentBody };
                delete retryBody.reasoning_effort;
                const r = await customFetch(url, { ...fetchOptions, body: JSON.stringify(retryBody) });
                if (r.ok || r.status !== 400) {
                    response = r;
                    currentBody = retryBody;
                }
            }

            if (!response.ok && response.status === 400 && (currentBody.thinking || currentBody.thinking_budget !== undefined)) {
                console.warn(`[${PLUGIN_NAME}] API 返回 HTTP 400，怀疑端点不支持非标准 thinking/thinking_budget，正在剥离重试...`);
                const retryBody = { ...currentBody };
                delete retryBody.thinking;
                delete retryBody.thinking_budget;
                const r = await customFetch(url, { ...fetchOptions, body: JSON.stringify(retryBody) });
                if (r.ok || r.status !== 400) {
                    response = r;
                    currentBody = retryBody;
                }
            }

            if (!response.ok && response.status === 400 && currentBody.reasoning_effort) {
                console.warn(`[${PLUGIN_NAME}] API 返回 HTTP 400，端点可能完全不支持思维链参数，正在剥离所有思考参数重试...`);
                const retryBody = { ...currentBody };
                delete retryBody.reasoning_effort;
                delete retryBody.thinking;
                delete retryBody.thinking_budget;
                const r = await customFetch(url, { ...fetchOptions, body: JSON.stringify(retryBody) });
                if (r.ok || r.status !== 400) {
                    response = r;
                    currentBody = retryBody;
                }
            }
        }

        // 2. 如果请求带有 tools 且报错 400/500，尝试 auto 协商；若仍失败直接报错提示 API 不支持 tools
        if (!response.ok && (response.status === 400 || response.status === 500) && currentBody.tools) {
            console.warn(`[${PLUGIN_NAME}] API 返回 HTTP ${response.status}，怀疑接口不支持指定 tool_choice，尝试转为 auto 重试...`);
            const retryBody = { ...currentBody, tool_choice: 'auto' };
            const autoRes = await customFetch(url, {
                ...fetchOptions,
                body: JSON.stringify(retryBody),
            });
            if (autoRes.ok) {
                response = autoRes;
                currentBody = retryBody;
            } else {
                let errText = '';
                try { errText = await autoRes.text(); } catch (_) {}
                const err = new Error(`大模型接口不支持工具调用 (Tool Call / Function Calling)。请在设置中关闭「结构化工具调用 (Tool Call)」开关，或更换支持 Tool Calling 的中转渠道。(HTTP ${autoRes.status})`);
                err.code = 'SDT_TOOLS_UNSUPPORTED';
                err.status = autoRes.status;
                err.responseText = errText;
                err.rawOutput = `【错误】: 当前 API 接口不支持工具调用 (Tool Call / Function Calling)\n【HTTP 状态码】: ${autoRes.status}\n【服务端返回报文】:\n${errText || '（无响应体）'}\n\n【排查建议】: 请在设置中关闭「结构化工具调用 (Tool Call)」以改用标准 JSON 模式，或联系中转站开启该模型渠道的 Function Calling 权限。`;
                throw err;
            }
        }

        // 3. 如果当前仍报错 400 且带有 response_format，尝试剥离 response_format
        if (!response.ok && response.status === 400 && currentBody.response_format) {
            console.warn(`[${PLUGIN_NAME}] API 返回 HTTP 400，怀疑模型不支持 response_format，正在剥离该参数重试...`);
            const retryBody = { ...currentBody };
            delete retryBody.response_format;
            response = await customFetch(url, {
                ...fetchOptions,
                body: JSON.stringify(retryBody),
            });
            if (response.ok) {
                currentBody = retryBody;
            }
        }

        // 4. 终极兜底：如果前面 tool 降级或 response_format 降级后依然 400，且请求中残留思维链参数，再次尝试剥离所有思维链参数
        if (!response.ok && response.status === 400 && (currentBody.thinking || currentBody.thinking_budget !== undefined || currentBody.reasoning_effort)) {
            console.warn(`[${PLUGIN_NAME}] 降级后依然返回 HTTP 400，正在彻底剥离所有思维链相关参数发起最后重试...`);
            const cleanBody = { ...currentBody };
            delete cleanBody.reasoning_effort;
            delete cleanBody.thinking;
            delete cleanBody.thinking_budget;
            response = await customFetch(url, {
                ...fetchOptions,
                body: JSON.stringify(cleanBody),
            });
        }

        return response;
    }

    function squashConsecutiveMessages(messages) {
        if (!Array.isArray(messages) || messages.length === 0) return [];
        const squashed = [];
        for (const msg of messages) {
            if (!msg || !msg.role) continue;
            const prev = squashed[squashed.length - 1];
            // If previous message has same role and neither has tool calls / responses
            if (prev && prev.role === msg.role && !prev.tool_calls && !msg.tool_calls && !prev.tool_call_id && !msg.tool_call_id) {
                const prevText = String(prev.content || '').trim();
                const currText = String(msg.content || '').trim();
                prev.content = [prevText, currText].filter(Boolean).join('\n\n');
            } else {
                squashed.push({ ...msg });
            }
        }
        return squashed;
    }

    function applyPostProcessPrompt(messages, store) {
        if (!store.postProcessEnabled) return;
        const presetKey = store.geminiJailbreakPreset || DEFAULT_JAILBREAK_PRESET;
        let promptText = store.postProcessPrompt;
        if (presetKey !== 'custom') {
            const preset = JAILBREAK_PRESETS[presetKey];
            if (preset?.postProcessPrompt && (!promptText || promptText === DEFAULT_POST_PROCESS_PROMPT)) {
                promptText = preset.postProcessPrompt;
            }
        }
        const raw = String(promptText || '').trim();
        if (!raw) return;

        const roleRegex = /<\|(system|user|assistant|model)\|>/gi;
        if (roleRegex.test(raw)) {
            // 与破限词完全相同的多轮标签解析
            const parts = raw.split(roleRegex);
            if (parts[0].trim()) {
                messages.push({ role: 'assistant', content: parts[0].trim() });
            }
            for (let i = 1; i < parts.length; i += 2) {
                const role = parts[i].toLowerCase() === 'model' ? 'assistant' : parts[i].toLowerCase();
                const content = (parts[i + 1] || '').trim();
                if (content) {
                    messages.push({ role, content });
                }
            }
            return;
        }

        const colonTurns = splitTurnsByColon(raw, 'assistant');
        if (colonTurns && colonTurns.length > 0) {
            for (const msg of colonTurns) {
                messages.push(msg);
            }
            return;
        }

        // 没有多轮标签时：默认作为 assistant 回合注入（若历史配置保留了 user_append/system 则兼顾）
        const role = store.postProcessRole || 'assistant';
        if (role === 'user_append') {
            const lastUser = messages.slice().reverse().find(m => m.role === 'user');
            if (lastUser) {
                lastUser.content += `\n\n[输出引导]\n${raw}`;
            } else {
                messages.push({ role: 'user', content: `[输出引导]\n${raw}` });
            }
        } else if (role === 'system') {
            const firstSystem = messages.find(m => m.role === 'system');
            if (firstSystem) {
                firstSystem.content += `\n\n[输出引导]\n${raw}`;
            } else {
                const lastUser = messages.slice().reverse().find(m => m.role === 'user');
                if (lastUser) {
                    lastUser.content += `\n\n[输出引导]\n${raw}`;
                } else {
                    messages.push({ role: 'system', content: raw });
                }
            }
        } else {
            messages.push({ role: 'assistant', content: raw });
        }
    }

    /* ===== [LOCAL PATCH 6.5.55] 失败重试 + 渠道自动降级 ===== */
const SDT_FALLBACK_MODELS = [
    '[pg]gemini-3.1-pro-preview-high',
    '[aistudio]gemini-3.1-pro-preview',
    '[pla]gemini-3.1-pro-preview',
    '[anti]gemini-3.8-flash',
    '[pg]gemini-3.8-flash-high',
    '[aistudio]gemini-3.8-flash',
];
const SDT_RETRY_PER_MODEL = 2;
const SDT_RETRY_BUDGET_MS = 300000;

/* ===== [LOCAL PATCH] 诊断日志（本地采集，手机端可一键导出） ===== */
const SDT_DIAG_KEY = 'rbq_sdt_diag_v1';
const SDT_DIAG_MAX_RECORDS = 30;
const SDT_DIAG_MAX_CHARS = 1600000;

function sdtDiag() {
    if (typeof window === 'undefined') return null;
    if (window.__SDT_DIAG) return window.__SDT_DIAG;
    let records = [];
    try {
        const raw = localStorage.getItem(SDT_DIAG_KEY);
        const parsed = raw ? JSON.parse(raw) : null;
        if (Array.isArray(parsed)) records = parsed;
    } catch (e) { records = []; }
    const persist = () => {
        try {
            let s = JSON.stringify(records);
            while (s.length > SDT_DIAG_MAX_CHARS && records.length > 1) { records.shift(); s = JSON.stringify(records); }
            localStorage.setItem(SDT_DIAG_KEY, s);
        } catch (e) {
            try { records.shift(); localStorage.setItem(SDT_DIAG_KEY, JSON.stringify(records)); } catch (e2) { /* ignore */ }
        }
    };
    const api = {
        records,
        add(type, data) {
            try {
                const rec = Object.assign({ t: new Date().toISOString(), type }, data || {});
                records.push(rec);
                if (records.length > SDT_DIAG_MAX_RECORDS) records.splice(0, records.length - SDT_DIAG_MAX_RECORDS);
                persist();
                try { if (typeof window.__SDT_ROUND_REFRESH === 'function') window.__SDT_ROUND_REFRESH(); } catch (e) { /* ignore */ }
                return rec;
            } catch (e) { return null; }
        },
        clear() {
            records.length = 0;
            try { localStorage.removeItem(SDT_DIAG_KEY); } catch (e) { /* ignore */ }
        },
        dump() {
            let store = {};
            try { store = getStore() || {}; } catch (e) { store = {}; }
            return {
                schema: 'rbq-sdt-diag/1',
                generatedAt: new Date().toISOString(),
                pluginVersion: (typeof PLUGIN_VERSION !== 'undefined' ? PLUGIN_VERSION : ''),
                env: {
                    baseUrl: store.openaiBaseUrl || '',
                    model: String(store.openaiModelCustom || '').trim() || store.openaiModel || '',
                    fallbackEnabled: store.modelFallbackEnabled !== false,
                    fallbackList: store.modelFallbackList || '',
                    preset: store.systemPromptPreset || '',
                    customPromptLen: String(store.customSystemPrompt || '').length,
                    minSegments: store.minSegments,
                    contextCount: store.contextCount,
                    multiCharOutput: !!store.multiCharOutput,
                    multiCharUseCoords: !!store.multiCharUseCoords,
                    geminiJailbreak: !!store.geminiJailbreak,
                    jailbreakPreset: store.geminiJailbreakPreset || '',
                    toolCallMode: !!store.toolCallMode,
                    markers: store.markers || '',
                    lorebookEnabled: !!store.lorebookEnabled,
                    lorebookBudget: store.lorebookBudget,
                    characterMemoryEnabled: !!store.characterMemoryEnabled,
                    // 6.5.59：姿势引擎变量是否真的在 chatMetadata 里（这是桥接能不能工作的前提）
                    poseVar: (function () {
                        try {
                            const ctx = (typeof window !== 'undefined' && window.SillyTavern && typeof window.SillyTavern.getContext === 'function')
                                ? window.SillyTavern.getContext() : null;
                            const vars = (ctx && ctx.chatMetadata && ctx.chatMetadata.variables) || null;
                            if (!vars) return { found: false, reason: 'noVariables' };
                            const keys = Object.keys(vars);
                            const engine = vars['姿势引擎'];
                            const flat = vars['姿势引擎.状态'];
                            const st = (engine && engine['状态']) || null;
                            const cur = st && st['当前'];
                            const used = st && st['已用'];
                            return {
                                found: !!(engine || flat !== undefined),
                                shape: flat !== undefined ? 'flat' : (engine ? 'nested' : 'none'),
                                keys: keys.slice(0, 20),
                                state: st ? {
                                    场次: st['场次'], 剩余: st['剩余'],
                                    越界: st['越界'], 换牌: st['换牌'],
                                    已用条数: Array.isArray(used) ? used.length : null
                                } : null,
                                current: Array.isArray(cur) ? cur.slice(0, 4) : (cur || null)
                            };
                        } catch (e) { return { found: false, reason: String((e && e.message) || e) }; }
                    })(),
                    // 6.5.59：上一次 tagger 实际拼出的 prompt 上下文（桥接/世界书自证）
                    lastTagger: (typeof window !== 'undefined' && window.__SDT_DIAG_CTX) || null
                },
                count: records.length,
                records
            };
        }
    };
    window.__SDT_DIAG = api;
    return api;
}

(function exposeSdtDiag() {
    try {
        window.RBQ_SDT_DIAG = {
            dump: () => sdtDiag().dump(),
            clear: () => sdtDiag().clear(),
            peek: () => sdtDiag().records.slice()
        };
    } catch (e) { /* ignore */ }
})();
/* ===== [END LOCAL PATCH] ===== */

/** 6.5.59：把「桥接 + 世界书」的自证位压成短字段，挂到 tagger-ok / tagger-fail 上。
 *  没有这份上下文时（比如旧存档直接失败在请求前），返回 { diagCtx: null } 而不是抛错。 */
function sdtDiagTaggerBits() {
    try {
        const dc = (typeof window !== 'undefined' && window.__SDT_DIAG_CTX) || null;
        if (!dc) return { diagCtx: null };
        const pose = (dc.storyFacts && dc.storyFacts.pose) || null;
        return {
            storyFacts: dc.storyFacts || null,
            poseId: (pose && pose.id) || '',
            poseClass: (pose && pose.className) || '',
            poseName: (pose && pose.name) || '',
            poseLock: !!dc.poseLockInPrompt,
            systemPromptLen: dc.systemPromptLen || 0,
            lorebook: dc.lorebook || null,
            lorebookSources: dc.sources || []
        };
    } catch (e) { return { diagCtx: null }; }
}

/** 6.5.60 本轮体检：把「姿势变量 / 体位锁定 / 世界书预算 / 出图重复」压成几行纯文本。
 *  手机端没有控制台，面板上要能直接看到这一轮到底带了什么。 */
function sdtRoundInspectLines() {
    const lines = [];
    let poseLive = null;
    try {
        const ctx = (typeof window !== 'undefined' && window.SillyTavern && typeof window.SillyTavern.getContext === 'function')
            ? window.SillyTavern.getContext() : null;
        const vars = (ctx && ctx.chatMetadata && ctx.chatMetadata.variables) || null;
        poseLive = (vars && vars['姿势引擎']) || null;
    } catch (e) { poseLive = null; }
    const st = (poseLive && poseLive['状态']) || null;
    const cur = (st && Array.isArray(st['当前'])) ? st['当前'] : null;
    lines.push(`【姿势变量】${poseLive ? '✅ 读得到' : '❌ 读不到（世界书没跑 / 不在当前聊天）'}`);
    if (cur && cur.length) lines.push(`  当前 ${cur[0]} · 主类 ${cur[1] || '?'} ${cur[2] || ''}`.trimEnd());
    if (st) {
        const cross = st['越界'];
        lines.push(`  场次 ${st['场次'] ?? '-'}｜剩余 ${st['剩余'] ?? '-'}｜越界 ${cross === true ? 'true（无视场景抽中）' : (cross ?? '-')}`);
    }
    let dc = null;
    try { dc = (typeof window !== 'undefined' && window.__SDT_DIAG_CTX) || null; } catch (e) { dc = null; }
    if (dc) {
        lines.push(`【体位锁定】${dc.poseLockInPrompt ? '✅ 已进 system prompt' : '❌ 没进 prompt'}（prompt ${dc.systemPromptLen || 0} 字符）`);
        const vocab = sdtPoseVocabLines((dc.storyFacts && dc.storyFacts.pose && dc.storyFacts.pose.className) || '');
        if (vocab.length) lines.push('  词面：' + vocab[0].replace('【体位词面】', ''));
        const lb = dc.lorebook || {};
        const budget = Number(lb.budget) || 0;
        const chars = Number(lb.chars) || 0;
        const tight = budget > 0 && chars >= Math.floor(budget * 0.95);
        lines.push(`【世界书】${lb.enabled ? '开' : '关'}｜命中 ${lb.activated || 0} 条 / ${chars} 字｜预算 ${budget}${tight ? '（⚠️ 顶满预算，靠后的条目被丢掉了）' : ''}`);
        if (Array.isArray(lb.titles) && lb.titles.length) {
            lines.push(`  标题：${lb.titles.slice(0, 6).join(' / ')}${lb.titles.length > 6 ? ' …' : ''}`);
        }
        if (Array.isArray(lb.ejsEntries) && lb.ejsEntries.length) {
            lines.push(`  ⚠️ ${lb.ejsEntries.length} 条含 EJS 源码被塞进 prompt（本该排除）`);
        }
    } else {
        lines.push('【体位锁定】本次会话还没有生成记录');
    }
    try {
        const recs = sdtDiag().records || [];
        let lastIdx = -1;
        for (let i = recs.length - 1; i >= 0; i--) {
            if (recs[i].type === 'tagger-ok' || recs[i].type === 'tagger-fail') { lastIdx = i; break; }
        }
        const last = lastIdx >= 0 ? recs[lastIdx] : null;
        if (last) {
            lines.push(`【上一轮】${last.type === 'tagger-ok' ? '✅ 出了规格' : '❌ 失败'}｜渠道 ${last.channel || '-'}｜模型 ${last.model || '-'}｜${last.elapsedMs || 0} ms`);
        }
        const payloads = recs.slice(lastIdx + 1).filter(r => r.type === 'nai-payload');
        if (payloads.length) {
            const seen = new Set();
            let dup = 0;
            for (const p of payloads) {
                const key = String(p.input || '');
                if (seen.has(key)) dup++; else seen.add(key);
            }
            lines.push(`【出图】${payloads.length} 张${dup ? `，⚠️ ${dup} 张与前面完全重复` : '，无重复'}`);
        }
        const gates = recs.slice(lastIdx + 1).filter(r => r.type === 'pose-gate');
        if (gates.length) lines.push(`【词法闸门】补回体位词 ${gates.length} 张（${gates.map(g => g.className + ' ' + g.added).join(' / ')}）`);
    } catch (e) { /* ignore */ }
    return lines;
}

function sdtIsRetryableError(err, signal) {
    if (signal && signal.aborted) return false;
    if (!err) return true;
    if (err.name === 'AbortError') return false;
    const code = String(err.code || '');
    if (/^MANGA_/.test(code)) return false;
    const msg = String(err.message || err);
    if (/HTTP\s*(401|403)\b/.test(msg)) return false;
    if (/Invalid token|无效的令牌|Unauthorized|Forbidden|请先填写/i.test(msg)) return false;
    return true;
}

function sdtBuildModelChain(store, target) {
    // 6.5.58 多渠道：模型名优先取渠道自己的，渠道没填才退回全局字段
    const primary = String((target && target.model) || '').trim() || String((store.openaiModelCustom || '').trim() || store.openaiModel || '').trim();
    const chain = [];
    const push = (m) => { const v = String(m || '').trim(); if (v && !chain.includes(v)) chain.push(v); };
    push(primary);
    const enabled = store.modelFallbackEnabled !== false;
    const chainBaseUrl = String((target && target.baseUrl) || store.openaiBaseUrl || '');
    if (enabled && /blqs\.cc/i.test(chainBaseUrl)) {
        SDT_FALLBACK_MODELS.forEach(push);
        String(store.modelFallbackList || '').split(/[\n,]+/).forEach(push);
    }
    return chain;
}

async function callOpenAiCompatible(messageId, trigger, opts = {}) {
    const o = opts || {};
    const sdtDiagHandle = sdtDiag();
    const sdtDiagT0 = Date.now();
    if (o.__noFallback) return await callOpenAiCompatibleOnce(messageId, trigger, o);
    const store = o.storeSnapshot || getStore();
    // 6.5.58 多渠道：外层按渠道链切换，内层沿用「模型降级 + 每模型重试」的旧逻辑
    const channels = resolveChannelChain(store);
    if (!channels.length) throw sdtChannelChainEmptyError(store);
    const useTool = !!store.toolCallMode;
    // 工具调用模式下全部渠道都明确「不支持」时直接报错，禁止静默降级成普通 JSON 解析
    if (useTool && channels.every(function (item) { return item.toolSupport === 'no'; })) throw sdtChannelNoToolError(channels);
    const startedAt = Date.now();
    const attemptLog = [];
    const channelLog = [];
    let attemptCount = 0;
    let modelCount = 0;
    let lastErr = null;
    let budgetHit = false;

    for (let chi = 0; chi < channels.length; chi++) {
        if (budgetHit) break;
        const channel = channels[chi];
        const channelStart = Date.now();
        const models = sdtBuildModelChain(store, channel);
        modelCount += models.length;
        let channelErr = null;
        let channelToolUnsupported = false;
        let channelEmpty = false;
        for (let ci = 0; ci < models.length; ci++) {
            if (budgetHit) break;
            const model = models[ci];
            const attempts = ci === 0 ? (SDT_RETRY_PER_MODEL + 1) : SDT_RETRY_PER_MODEL;
            for (let a = 1; a <= attempts; a++) {
                if (Date.now() - startedAt > SDT_RETRY_BUDGET_MS) { budgetHit = true; break; }
                if (a > 1) {
                    console.warn(`[${PLUGIN_NAME}] 重试 ${model} (第 ${a} 次 / 共 ${attempts} 次)`);
                    if (typeof toastr !== 'undefined' && typeof toastr.info === 'function') {
                        toastr.info(`请求失败，正在重试 ${model}（${a}/${attempts}）`, PLUGIN_NAME);
                    }
                }
                attemptCount++;
                try {
                    const result = await callOpenAiCompatibleOnce(messageId, trigger, Object.assign({}, o, { modelOverride: model, channel: channel }));
                    if (chi > 0 || ci > 0 || a > 1) {
                        console.info(`[${PLUGIN_NAME}] 已由「${channel.name}」的 ${model} 成功返回`);
                        if (typeof toastr !== 'undefined' && typeof toastr.success === 'function') {
                            toastr.success(`已由「${channel.name}」的 ${model} 成功返回`, PLUGIN_NAME);
                        }
                    }
                    // 只有真的拿到 tool_calls 才敢标「支持工具调用」——内部剥离 tools 兜底成普通 JSON 也算成功，但不能当作能力证据
                    reportChannelResult(store, channel.id, true, { latencyMs: Date.now() - channelStart, toolSupport: (useTool && result && result.isToolCall === true) ? 'yes' : '' });
                    try {
                        sdtDiagHandle && sdtDiagHandle.add('tagger-ok', {
                            trigger: (typeof trigger === 'string' ? trigger : JSON.stringify(trigger || '')),
                            messageId: messageId,
                            channel: channel.name,
                            channelId: channel.id,
                            model: model,
                            primaryModel: (channels[0] && channels[0].model) || '',
                            attempt: a,
                            chainIndex: ci,
                            channelIndex: chi,
                            chain: models,
                            elapsedMs: Date.now() - sdtDiagT0,
                            isToolCall: !!(result && result.isToolCall),
                            ...sdtDiagTaggerBits(),
                            toolName: (result && result.toolName) || '',
                            reasoning: String((result && result.reasoning) || '').slice(0, 8000),
                            rawReply: String((result && result.rawReply) || '').slice(0, 4000),
                            rawOutput: String((result && result.rawOutput) || '').slice(0, 80000)
                        });
                    } catch (e) { /* ignore */ }
                    return result;
                } catch (err) {
                    lastErr = err;
                    channelErr = err;
                    if (o.signal && o.signal.aborted) throw err;
                    if (err && err.name === 'AbortError') throw err;
                    const kind = sdtClassifyChannelFailure(err, o.signal);
                    // 配置缺失属于用户设置问题，换渠道也没意义，原样抛出
                    if (kind === 'config') throw err;
                    if (kind === 'tool') channelToolUnsupported = true;
                    if (kind === 'empty') channelEmpty = true;
                    const brief = sdtBriefError(err);
                    const line = channel.name + ' · ' + model + ' 第' + a + '次: ' + brief;
                    attemptLog.push(line);
                    console.warn('[' + PLUGIN_NAME + '] ' + line);
                    // 漫画协议错误换渠道也没用，原样抛；其余（401/403/限流/网络）只放弃本渠道，继续走后一条
                    if (/^MANGA_/.test(String(err.code || ''))) throw err;
                    if (!sdtIsRetryableError(err, o.signal)) break;
                }
            }
            if (budgetHit) break;
            if (ci < models.length - 1) {
                console.warn(`[${PLUGIN_NAME}] ${model} 连续失败，切换到 ${models[ci + 1]}`);
                if (typeof toastr !== 'undefined' && typeof toastr.warning === 'function') {
                    toastr.warning(`${model} 连续失败，切换到 ${models[ci + 1]}`, PLUGIN_NAME);
                }
            }
        }
        const channelBrief = channelErr ? sdtBriefError(channelErr) : '未知错误';
        const channelHint = channelToolUnsupported ? '（不支持工具调用）' : (channelEmpty ? '（响应为空，多为 Max Tokens 被思维链占满）' : '');
        channelLog.push('渠道「' + channel.name + '」（' + (channel.baseUrl || '') + ' / ' + (channel.model || '') + '）：' + channelBrief + channelHint);
        reportChannelResult(store, channel.id, false, {
            error: channelBrief,
            latencyMs: Date.now() - channelStart,
            toolSupport: channelToolUnsupported ? 'no' : '',
        });
        if (!budgetHit && chi < channels.length - 1) {
            const nextChannel = channels[chi + 1];
            console.warn('[' + PLUGIN_NAME + '] 渠道「' + channel.name + '」全部模型失败，切换到「' + nextChannel.name + '」');
            if (typeof toastr !== 'undefined' && typeof toastr.warning === 'function') {
                toastr.warning('渠道「' + channel.name + '」失败，切换到「' + nextChannel.name + '」', PLUGIN_NAME);
            }
        }
    }

    const secs = Math.round((Date.now() - startedAt) / 1000);
    const multi = channels.length > 1;
    const scope = multi ? (channels.length + ' 条渠道 / ' + modelCount + ' 个模型') : (modelCount + ' 个模型');
    const head = budgetHit
        ? 'tagger API 全部渠道失败：已用满 ' + Math.round(SDT_RETRY_BUDGET_MS / 1000) + 's 重试预算（' + attemptCount + ' 次尝试 / ' + scope + '，耗时 ' + secs + 's）'
        : 'tagger API 全部渠道失败（' + attemptCount + ' 次尝试 / ' + scope + '，耗时 ' + secs + 's）';
    const body = attemptLog.map(function (item, index) { return '  ' + (index + 1) + '. ' + item; }).join('\n');
    const channelSection = multi
        ? '\n\n【每条渠道的最终判定】\n' + channelLog.map(function (item, index) { return '  ' + (index + 1) + '. ' + item; }).join('\n')
        : '';
    const err = new Error(head + '\n' + body + channelSection);
    err.code = 'SDT_ALL_MODELS_FAILED';
    err.rawOutput = attemptLog.join('\n\n');
    err.retryError = lastErr;
    err.channels = channelLog;
    try {
        sdtDiagHandle && sdtDiagHandle.add('tagger-fail', {
            trigger: (typeof trigger === 'string' ? trigger : JSON.stringify(trigger || '')),
            messageId: messageId,
            primaryModel: (channels[0] && channels[0].model) || '',
            channels: channels.map(function (item) { return { id: item.id, name: item.name, model: item.model, toolSupport: item.toolSupport }; }),
            elapsedMs: Date.now() - sdtDiagT0,
            budgetHit: budgetHit,
            ...sdtDiagTaggerBits(),
            attempts: attemptLog,
            channelVerdicts: channelLog,
            message: String(head + '\n' + body + channelSection).slice(0, 6000),
            lastRawOutput: String((lastErr && lastErr.rawOutput) || '').slice(0, 20000),
            lastMessage: String((lastErr && lastErr.message) || '').slice(0, 4000)
        });
    } catch (e) { /* ignore */ }
    throw err;
}
/* ===== [END LOCAL PATCH] ===== */

async function callOpenAiCompatibleOnce(messageId, trigger, { signal, retryWithoutLorebook = false, promptSnapshot = null, forceJsonMode = false, modelOverride = '', channel = null } = {}) {
        const liveStore = getStore();
        let layeredSnapshot = promptSnapshot || (liveStore.enhancedContext === 'v_manga_layered_v1'
            ? captureLayeredMangaPromptSnapshot(liveStore) : null);
        // 6.5.49: forceJsonMode = 工具调用没拿到结果后的一次性普通 JSON 重试；只改本次请求，不动用户设置。
        if (forceJsonMode && layeredSnapshot?.storeSnapshot) {
            layeredSnapshot = { ...layeredSnapshot, storeSnapshot: { ...layeredSnapshot.storeSnapshot, toolCallMode: false } };
        }
        const baseStore = layeredSnapshot?.storeSnapshot || liveStore;
        const store = forceJsonMode ? { ...baseStore, toolCallMode: false } : baseStore;
        // 6.5.58 多渠道：URL / 密钥 / 模型都取自当前渠道；没传渠道时退回主渠道（等价于 6.5.57 的单渠道行为）
        const channelTarget = channel || sdtPrimaryChannelTarget(store) || null;
        const url = normalizeBaseUrl(channelTarget && channelTarget.baseUrl);
        if (!url) throw new Error('请先填写 OpenAI 兼容接口 Base URL');
        const modelName = modelOverride || String((channelTarget && channelTarget.model) || '').trim() || (store.openaiModelCustom || '').trim() || store.openaiModel;
        if (!modelName) throw new Error('请先填写模型名称');
        const channelApiKey = String((channelTarget && channelTarget.apiKey) || store.openaiApiKey || '').trim();
        checkUrlSafety(url);
        const { payload, rawLorebooks, requestContext, promptBundle } = buildRequestPayload(messageId, trigger, { skipLorebook: retryWithoutLorebook, promptSnapshot: layeredSnapshot });
        logTaggerPayload('tagger request body', payload);

        const systemPrompt = promptBundle ? promptBundle.instructionText : getSystemPromptWithPresets(store, !!(payload.characterCardInfo || payload.characterCardInfo_base64), messageId);
        const ecSysPrompt = promptBundle ? '' : getEnhancedContextSystemPrompt(getRequestEnhancedContext(store));
        const toolRule = !promptBundle && store.toolCallMode ? DRAW_SPEC_TOOL_RULE.trim() : '';

        // Keep system directives together at the start of the request.
        // [阶段1·桥接] 体位锁定段落套在组装点：layered manga 的 instructionText 在 getSystemPromptWithPresets 提前 return，套这里才能全通道覆盖
        const fullSystemPrompt = applyPoseDirective([systemPrompt, ecSysPrompt, toolRule].filter(Boolean).join('\n\n'), payload.storyFacts || null);

        // [6.5.59 诊断自证] 把「桥接是否真的生效 / 世界书是否真的进了 prompt」落进诊断包：
        // 之前的 dump 只有模型回包，无法回答「姿势变量读到了吗」「世界书命中几条」「是不是把 EJS 源码塞进了 prompt」。
        try {
            const lbList = Array.isArray(rawLorebooks) ? rawLorebooks : [];
            const lbChars = lbList.reduce((n, e) => n + String((e && e.content) || '').length, 0);
            const lbEjs = lbList.filter(e => /<%|%>/.test(String((e && e.content) || '')));
            window.__SDT_DIAG_CTX = {
                storyFacts: (payload && payload.storyFacts) || null,
                poseLockInPrompt: /【体位锁定】/.test(String(fullSystemPrompt || '')),
                systemPromptLen: String(fullSystemPrompt || '').length,
                promptBundle: !!promptBundle,
                toolMode: !!(store && store.toolCallMode),
                lorebook: {
                    enabled: !!(store && store.lorebookEnabled),
                    budget: store && store.lorebookBudget,
                    activated: lbList.length,
                    chars: lbChars,
                    ejsEntries: lbEjs.map(e => ({ uid: e.uid, source: e.sourceName || '', len: String((e && e.content) || '').length })),
                    titles: lbList.slice(0, 40).map(e => String((e && e.comment) || '').slice(0, 32)),
                },
                sources: (Array.isArray(store && store.lorebookSources) ? store.lorebookSources : []).map(s => ({
                    name: s && s.name, enabled: !(s && s.enabled === false), entryCount: (s && s.entryCount) || 0,
                })),
            };
        } catch (e) { /* 诊断失败绝不影响请求 */ }

        const standardRequest = buildStandardDrawRequest(fullSystemPrompt, payload, store, promptBundle);
        let messages = standardRequest?.messages;
        let requestTool = standardRequest?.tool;
        if (!standardRequest) {
            const isFullContextTool = store.provider !== 'custom' && store.toolCallMode && store.toolInputInDescription;
            if (isFullContextTool) {
                messages = [
                    { role: 'system', content: getReorganizedSystemPrompt(store) },
                    { role: 'user', content: getReorganizedUserMessage(store) },
                ];
                requestTool = getDrawSpecTool(store, promptBundle, payload, fullSystemPrompt);
            } else {
                const jailbreakPrompt = getActiveJailbreakPrompt(store);
                const rawMessages = (store.geminiJailbreak && jailbreakPrompt)
                    ? parseJailbreakMessages(jailbreakPrompt, fullSystemPrompt)
                    : [{ role: 'system', content: fullSystemPrompt }];

                const userContent = (store.geminiJailbreak && (store.geminiJailbreakPreset === 'render_pipeline_v2' || store.geminiJailbreakPreset === 'kami_gase'))
                    ? wrapPayloadInRenderTelemetryV2(payload)
                    : (store.geminiJailbreak && store.geminiJailbreakPreset === 'render_pipeline')
                    ? wrapPayloadInRenderTelemetry(payload)
                    : JSON.stringify(payload, null, 2);
                rawMessages.push({ role: 'user', content: userContent });

                applyPostProcessPrompt(rawMessages, store);

                // Merge any consecutive same-role messages if enabled
                messages = store.squashMessages !== false
                    ? squashConsecutiveMessages(rawMessages)
                    : rawMessages;

                if (store.toolCallMode) {
                    requestTool = getDrawSpecTool(store, promptBundle, payload);
                }
            }
        }

        const reqBody = {
            model: modelName,
            temperature: 0.2,
            stream: false,
            messages,
            ...buildThinkingParams(store),
        };

        if (store.toolCallMode) {
            reqBody.tools = [requestTool || getDrawSpecTool(store, promptBundle, payload, store.toolInputInDescription ? fullSystemPrompt : '')];
            reqBody.tool_choice = { type: 'function', function: { name: 'generate_draw_spec' } };
            reqBody.stream = true; // 必须开启流式，以兼容各类中转代理对 Gemini 工具调用的特殊要求
        } else {
            reqBody.response_format = { type: 'json_object' };
        }

        const response = await callApiWithJsonFallback(url, {
            method: 'POST',
            signal,
            headers: {
                'Content-Type': 'application/json',
                ...(channelApiKey ? { Authorization: `Bearer ${channelApiKey}` } : {}),
            },
        }, reqBody);
        if (!response.ok) {
            const errText = await response.text();
            const isInputWafHttpError = /sensitive words|prohibited use policy|the prompt could not be submitted|content_filter|prohibited_content|safety/i.test(errText);
            const hasLorebookAttached = !!(payload.lorebook?.length || payload.lorebook_base64 || payload.characterCardInfo || payload.characterCardInfo_base64);
            if (store.lorebookWafRetry && isInputWafHttpError && !retryWithoutLorebook && hasLorebookAttached) {
                console.warn(`[${PLUGIN_NAME}] ⚠️ HTTP ${response.status} 命中 Google 前置输入审核，正在自动剥离世界书发起纯净正文自愈重试...`);
                toastr.warning('世界书触发 Google 敏感词审核，正在自动剥离世界书保底重试...', PLUGIN_NAME);
                assertMangaRequestContext(requestContext);
                return await callOpenAiCompatibleOnce(messageId, trigger, { signal, retryWithoutLorebook: true, promptSnapshot: layeredSnapshot, forceJsonMode, modelOverride, channel });
            }
            throw new Error(`tagger API 请求失败: HTTP ${response.status} ${errText}`);
        }

        let json;
        let toolFallbackResult = null;
        const ct = response.headers.get('content-type') || '';
        const isSseStream = (ct.includes('text/event-stream') || reqBody.stream === true) && response.body && typeof response.body.getReader === 'function';

        // 6.5.49: 请求了 tools 却没拿到工具调用：先从正文/思维链里找分镜 JSON，找不到就去掉 tools 用普通 JSON 模式重试一次。
        const recoverMissingToolCall = async (finishReason, texts, rawText) => {
            const requestedTool = reqBody.tools[0];
            const recovered = recoverToolArgumentsFromText(texts, requestedTool);
            if (recovered) {
                console.info(`[${PLUGIN_NAME}] 模型未返回 tool_calls，已从正文中解析出 ${requestedTool.function.name} 参数并采用`);
                return { recovered };
            }
            const relayError = (texts || []).find(isRelayErrorText);
            if (relayError) throw makeRelayErrorTextError(relayError);
            assertMangaRequestContext(requestContext);
            if (signal?.aborted) {
                throw signal.reason && typeof signal.reason.message === 'string'
                    ? signal.reason : Object.assign(new Error('大模型请求已取消'), { name: 'AbortError' });
            }
            console.warn(`[${PLUGIN_NAME}] ⚠️ 模型未返回工具调用参数${finishReason ? ` (finish_reason: ${finishReason})` : ''}，自动去掉 tools 改用普通 JSON 模式重试一次`);
            if (typeof toastr !== 'undefined' && typeof toastr.info === 'function') toastr.info('模型没按工具调用返回，已自动改用普通模式重试', PLUGIN_NAME);
            try {
                return { result: await callOpenAiCompatibleOnce(messageId, trigger, {
                    signal, retryWithoutLorebook, promptSnapshot: promptSnapshot || layeredSnapshot, forceJsonMode: true, modelOverride, channel }) };
            } catch (retryErr) {
                if (retryErr?.name === 'AbortError' || signal?.aborted
                    || /^(?:SDT_TOOL_RESPONSE_BLOCKED|SDT_TOOL_RESPONSE_TRUNCATED|SDT_RELAY_ERROR_TEXT)$/.test(String(retryErr?.code || ''))
                    || /^MANGA_/.test(String(retryErr?.code || ''))) throw retryErr;
                const err = makeToolFallbackError(finishReason, rawText, true);
                err.retryError = retryErr;
                err.rawOutput += `\n\n【普通 JSON 模式重试的错误】: ${retryErr?.message || String(retryErr)}${retryErr?.rawOutput ? `\n${retryErr.rawOutput}` : ''}`;
                throw err;
            }
        };
        const synthesizeToolEnvelope = (args, finishReason, content, reasoning) => ({
            choices: [{
                finish_reason: finishReason || 'stop',
                message: {
                    tool_calls: [{ type: 'function', function: { name: reqBody.tools[0].function.name, arguments: JSON.stringify(args) } }],
                    content: content || '',
                    reasoning_content: reasoning || '',
                },
            }],
        });

        if (isSseStream) {
            const { sseState, rawStreamText } = await readSseCompletion(response, signal, null, reqBody.tools?.[0]?.function?.name || '');

            // 容错：如果流中未检测到 SSE 格式 (data:)，但实际上返回了完整的单体 JSON（例如反代未走流式包装）
            if (!sseState.accumulatedArgs && !sseState.accumulatedContent && !sseState.hasSafetyBlock && rawStreamText.trim()) {
                const trimmedRaw = rawStreamText.trim();
                if (trimmedRaw.startsWith('{') && trimmedRaw.endsWith('}')) {
                    try {
                        const parsedDirect = JSON.parse(trimmedRaw);
                        if (parsedDirect && (parsedDirect.choices || parsedDirect.candidates || parsedDirect.error || parsedDirect.promptFeedback)) {
                            console.info(`[${PLUGIN_NAME}] 流式通道接收到了标准非流式 JSON 对象，直接采纳`);
                            json = parsedDirect;
                        }
                    } catch (_e) {}
                }
            }

            if (!json) {
                // 调试信息：输出实际解包结果
                if (sseState.rawDebugChunks.length > 0) {
                    console.info(`[${PLUGIN_NAME}] SSE 流解包统计: 提取工具参数 ${sseState.accumulatedArgs.length} 字符, 提取正文 ${sseState.accumulatedContent.length} 字符, 提取思维链 ${sseState.accumulatedReasoning.length} 字符`, sseState.rawDebugChunks);
                }

                // 若模型把输出放进了思维链
                if (!sseState.accumulatedArgs && !sseState.accumulatedContent && sseState.accumulatedReasoning) {
                    sseState.accumulatedContent = sseState.accumulatedReasoning;
                }

                // 如果两者都为空，说明流式未产出内容
                if (!sseState.accumulatedArgs && !sseState.accumulatedContent && !sseState.toolCalls?.length) {
                    const isSafetyReason = sseState.hasSafetyBlock
                        || (sseState.lastFinishReason && /content_filter|safety|prohibited|recitation|blocklist|spii/i.test(sseState.lastFinishReason));

                    if (isSafetyReason) {
                        const safetyDetail = sseState.safetyReason || `finish_reason: ${sseState.lastFinishReason}`;
                        const isInputWafBlock = /sensitive words|the prompt could not be submitted|prohibited use policy|content_filter|safety|prohibited/i.test(safetyDetail);

                        // 🛡️ 自动自愈重试：若当前请求携带了世界书/角色卡，且触发了 Google 前置输入审核阻断，自动剥离世界书发起重试
                        const hasLorebookAttached = !!(payload.lorebook?.length || payload.lorebook_base64 || payload.characterCardInfo || payload.characterCardInfo_base64);
                        if (store.lorebookWafRetry && isInputWafBlock && !retryWithoutLorebook && hasLorebookAttached) {
                            console.warn(`[${PLUGIN_NAME}] ⚠️ 检测到触发 Google 官方前置输入审核熔断 (${safetyDetail})。判定为世界书/角色卡中存在受限词，正在自动剥离世界书发起纯净正文自愈重试...`);
                            toastr.warning('世界书触发 Google 敏感词审核，正在自动剥离世界书保底重试...', PLUGIN_NAME);
                            assertMangaRequestContext(requestContext);
                            return await callOpenAiCompatibleOnce(messageId, trigger, { signal, retryWithoutLorebook: true, promptSnapshot: layeredSnapshot, forceJsonMode, modelOverride, channel });
                        }

                        const err = new Error(`大模型/中转代理触发了官方前置内容安全审查拦截 (${safetyDetail})。大模型拒绝生成内容并终止了工具调用。`);
                        err.code = 'SDT_TOOL_RESPONSE_BLOCKED';
                        err.debugInfo = {
                            reason: `大模型触发前置安全策略熔断 (${safetyDetail})`,
                            model: modelName,
                            llmOutput: '(空 - 服务端由于安全策略中断，未生成任何正文)',
                            chunks: sseState.rawDebugChunks,
                        };
                        err.rawOutput = `【错误】: 大模型触发内容审查拦截 (${safetyDetail})。\n【排查建议】: 本次请求被模型官方安全过滤（NSFW/敏感词/违规内容）阻断，大模型拒绝作答并中断了工具调用。建议尝试开启「开启破限」选项、对世界书/角色卡/提示词脱敏、精简敏感剧情，或在代理/中转端关闭安全过滤。`;
                        throw err;
                    }

                    if (/^(?:length|max_tokens)$/i.test(String(sseState.lastFinishReason || ''))) {
                        const err = new Error('大模型输出因达到最大 Token (Max Tokens) 限制而被截断，未能完整返回分镜数据。请在设置中调大 Max Tokens 或精简上下文。');
                        err.code = 'SDT_TOOL_RESPONSE_TRUNCATED';
                        err.debugInfo = {
                            reason: '大模型输出被 Max Tokens 截断 (finish_reason: length)',
                            model: modelName,
                            llmOutput: '(空)',
                            chunks: sseState.rawDebugChunks,
                        };
                        err.rawOutput = `【错误】: 大模型输出达到 Max Tokens 截断限制 (finish_reason: length)。\n【排查建议】: 请在设置中调大 Max Tokens，或减少带入的上下文层数与世界书条目。`;
                        throw err;
                    }

                    if (reqBody.tools) {
                        const outcome = await recoverMissingToolCall(sseState.lastFinishReason, [], rawStreamText);
                        return outcome.result;
                    }

                    const finishReasonInfo = sseState.lastFinishReason ? ` (finish_reason: ${sseState.lastFinishReason})` : '';
                    const err = new Error(`大模型未输出任何内容${finishReasonInfo}（可能被代理静默拦截或发生网络异常）。建议检查代理日志或在设置中切换模型。`);
                    err.debugInfo = {
                        reason: `未获得任何有效正文${finishReasonInfo}`,
                        model: modelName,
                        llmOutput: '(空)',
                        chunks: sseState.rawDebugChunks,
                    };
                    throw err;
                } else {
                    if (reqBody.tools && !sseState.accumulatedArgs && !sseState.toolCalls?.length) {
                        const isSafetyReason = sseState.hasSafetyBlock
                            || (sseState.lastFinishReason && /content_filter|safety|prohibited|recitation|blocklist|spii/i.test(sseState.lastFinishReason));

                        if (isSafetyReason) {
                            const safetyDetail = sseState.safetyReason || `finish_reason: ${sseState.lastFinishReason}`;
                            const err = new Error(`大模型/中转代理触发了官方前置内容安全审查拦截 (${safetyDetail})。大模型拒绝生成内容并终止了工具调用。`);
                            err.code = 'SDT_TOOL_RESPONSE_BLOCKED';
                            err.debugInfo = {
                                reason: `大模型触发前置安全策略熔断 (${safetyDetail})`,
                                model: modelName,
                                llmOutput: sseState.accumulatedContent || '(空)',
                                chunks: sseState.rawDebugChunks,
                            };
                            err.rawOutput = `【错误】: 大模型触发内容审查拦截 (${safetyDetail})。\n【服务端原始响应正文】:\n${sseState.accumulatedContent || '（空）'}\n\n【排查建议】: 本次请求被模型官方安全过滤（NSFW/敏感词）阻断。建议尝试开启「开启破限」选项、对提示词脱敏或在代理端关闭安全过滤。`;
                            throw err;
                        }

                        if (/^(?:length|max_tokens)$/i.test(String(sseState.lastFinishReason || ''))) {
                            const err = new Error('大模型输出因达到最大 Token (Max Tokens) 限制而被截断，未能完整返回工具调用数据。请在设置中调大 Max Tokens 或精简上下文。');
                            err.code = 'SDT_TOOL_RESPONSE_TRUNCATED';
                            err.debugInfo = {
                                reason: '大模型输出被 Max Tokens 截断 (finish_reason: length)',
                                model: modelName,
                                llmOutput: sseState.accumulatedContent || '(空)',
                                chunks: sseState.rawDebugChunks,
                            };
                            err.rawOutput = `【错误】: 大模型输出达到 Max Tokens 截断限制 (finish_reason: length)。\n【服务端原始响应正文】:\n${sseState.accumulatedContent || '（空）'}\n\n【排查建议】: 请在设置中调大 Max Tokens。`;
                            throw err;
                        }

                        const outcome = await recoverMissingToolCall(sseState.lastFinishReason,
                            [sseState.accumulatedContent, sseState.accumulatedReasoning], sseState.accumulatedContent || rawStreamText);
                        if (!outcome.recovered) return outcome.result;
                        toolFallbackResult = synthesizeToolEnvelope(outcome.recovered, sseState.lastFinishReason,
                            sseState.accumulatedContent, sseState.accumulatedReasoning);
                    }
                    json = toolFallbackResult || {
                        choices: [{
                            finish_reason: sseState.lastFinishReason || 'stop',
                            message: {
                                ...(sseState.toolCalls?.length ? { tool_calls: sseState.toolCalls.map(call => ({ type: 'function', function: { name: call.name, arguments: call.arguments } })) } : {}),
                                ...(sseState.hasSafetyBlock ? { refusal: sseState.safetyReason || 'refusal' } : {}),
                                content: sseState.accumulatedContent,
                                reasoning_content: sseState.accumulatedReasoning
                            }
                        }]
                    };
                }
            }
        } else {
            json = await safeReadJsonResponse(response);
        }

        assertMangaRequestContext(requestContext);

        if (json?.error) {
            const err = new Error(`大模型返回错误: ${json.error.message || JSON.stringify(json.error)}`);
            err.rawOutput = JSON.stringify(json, null, 2);
            throw err;
        }

        if (reqBody.tools) {
            const choice = json?.choices?.[0];
            const candidate = json?.candidates?.[0];
            const finishReason = choice?.finish_reason || candidate?.finishReason;
            const refusal = choice?.message?.refusal || candidate?.refusal;
            const isSafetyReason = (finishReason && /content_filter|safety|prohibited|recitation|blocklist|spii/i.test(String(finishReason)))
                || (refusal && typeof refusal === 'string' && refusal.trim())
                || !!json?.promptFeedback?.blockReason;

            if (isSafetyReason) {
                const safetyDetail = `finish_reason: ${refusal ? 'refusal' : finishReason || json?.promptFeedback?.blockReason || 'SAFETY'}`;
                const isInputWafBlock = /sensitive words|the prompt could not be submitted|prohibited use policy|content_filter|safety|prohibited/i.test(safetyDetail);
                const hasLorebookAttached = !!(payload.lorebook?.length || payload.lorebook_base64 || payload.characterCardInfo || payload.characterCardInfo_base64);
                if (store.lorebookWafRetry && isInputWafBlock && !retryWithoutLorebook && hasLorebookAttached) {
                    console.warn(`[${PLUGIN_NAME}] ⚠️ 非流式检测到触发内容审查拦截 (${safetyDetail})，正在自动剥离世界书发起自愈重试...`);
                    toastr.warning('世界书触发敏感词审核，正在自动剥离世界书保底重试...', PLUGIN_NAME);
                    assertMangaRequestContext(requestContext);
                    return await callOpenAiCompatibleOnce(messageId, trigger, { signal, retryWithoutLorebook: true, promptSnapshot: layeredSnapshot, forceJsonMode, modelOverride, channel });
                }
                const err = new Error(`大模型/中转代理触发了官方前置内容安全审查拦截 (${safetyDetail})。大模型拒绝生成内容并终止了工具调用。`);
                err.code = 'SDT_TOOL_RESPONSE_BLOCKED';
                err.debugInfo = {
                    reason: `大模型触发前置安全策略熔断 (${safetyDetail})`,
                    model: modelName,
                    llmOutput: choice?.message?.content || '(空 - 服务端由于安全策略中断，未生成任何正文)',
                };
                err.rawOutput = `【错误】: 大模型触发内容审查拦截 (${safetyDetail})。\n【排查建议】: 本次请求被模型官方安全过滤（NSFW/敏感词/违规内容）阻断，未生成任何分镜内容或工具调用数据。建议精简敏感剧情、对世界书/提示词脱敏，或在代理端关闭安全过滤。`;
                throw err;
            }

            if (/^(?:length|max_tokens)$/i.test(String(finishReason || ''))) {
                const err = new Error('大模型输出因达到最大 Token (Max Tokens) 限制而被截断，未能完整返回分镜数据。请在设置中调大 Max Tokens 或精简上下文。');
                err.code = 'SDT_TOOL_RESPONSE_TRUNCATED';
                err.debugInfo = {
                    reason: '大模型输出被 Max Tokens 截断 (finish_reason: length)',
                    model: modelName,
                    llmOutput: choice?.message?.content || '(空)',
                };
                err.rawOutput = `【错误】: 大模型输出达到 Max Tokens 截断限制 (finish_reason: length)。\n【排查建议】: 请在设置中调大 Max Tokens，或减少带入的上下文层数与世界书条目。`;
                throw err;
            }

            const hasTool = getCompletionToolCalls(json).length > 0;
            if (!hasTool) {
                const content = choice?.message?.content ?? choice?.text
                    ?? (Array.isArray(candidate?.content?.parts)
                        ? candidate.content.parts.filter(part => !part?.thought && typeof part?.text === 'string').map(part => part.text).join('') : '');
                const reasoning = choice?.message?.reasoning_content || choice?.reasoning_content || '';
                const outcome = await recoverMissingToolCall(finishReason, [content, reasoning],
                    (typeof content === 'string' && content) || JSON.stringify(json, null, 2));
                if (!outcome.recovered) return outcome.result;
                json = synthesizeToolEnvelope(outcome.recovered, finishReason, typeof content === 'string' ? content : '', reasoning);
            }
        }

        if (reqBody.tools) {
            try {
                const call = selectCompletionToolCall(getCompletionToolCalls(json), reqBody.tools[0].function.name);
                validateCompletionToolArguments(call?.arguments, reqBody.tools[0]);
            } catch (err) {
                err.rawOutput = JSON.stringify(json, null, 2);
                throw err;
            }
        }

        if (forceJsonMode) {
            // 6.5.49: 兜底重试必须真的拿到分镜 JSON；否则普通 JSON 解析会把垃圾当成「无需生图」静默吞掉。
            const choice = json?.choices?.[0];
            const parts = Array.isArray(json?.candidates?.[0]?.content?.parts) ? json.candidates[0].content.parts : [];
            const text = choice?.message?.content ?? choice?.text ?? parts.filter(part => !part?.thought && typeof part?.text === 'string').map(part => part.text).join('');
            const reasoning = choice?.message?.reasoning_content || choice?.reasoning_content || '';
            if (isRelayErrorText(text)) throw makeRelayErrorTextError(text);
            if (!recoverToolArgumentsFromText([text, reasoning], { type: 'function', function: { name: 'generate_draw_spec' } })) {
                const err = new Error('普通 JSON 模式重试也没有返回有效的分镜 JSON');
                err.code = 'SDT_JSON_RETRY_INVALID';
                err.rawOutput = typeof text === 'string' && text ? text : JSON.stringify(json, null, 2);
                throw err;
            }
        }

        logTaggerPayload('tagger raw response', json);
        const normalized = validateStructuredResult(normalizeTaggerResult(json, rawLorebooks, requestContext.manga ? requestContext : null));
        logTaggerPayload('tagger normalized result', normalized);
        if (retryWithoutLorebook) {
            toastr.warning('由于世界书含受限敏感词，本次已自动剥离世界书保底完成生图分镜', PLUGIN_NAME);
        }
        return normalized;
    }

    async function callCustomHttp(messageId, trigger, { signal, promptSnapshot = null } = {}) {
        const liveStore = getStore();
        const layeredSnapshot = promptSnapshot || (liveStore.enhancedContext === 'v_manga_layered_v1'
            ? captureLayeredMangaPromptSnapshot(liveStore) : null);
        const store = layeredSnapshot?.storeSnapshot || liveStore;
        const url = String(store.customUrl || '').trim();
        if (!url) throw new Error('请先填写自定义 HTTP 接口地址');
        checkUrlSafety(url);
        const headers = { 'Content-Type': 'application/json' };
        if (store.customApiKey) {
            const headerName = store.customApiKeyHeader || 'Authorization';
            headers[headerName] = headerName.toLowerCase() === 'authorization' ? `Bearer ${store.customApiKey}` : store.customApiKey;
        }
        const { payload, rawLorebooks, requestContext } = buildRequestPayload(messageId, trigger, { promptSnapshot: layeredSnapshot });
        logTaggerPayload('tagger request body', payload);
        const response = await smartFetch(url, {
            method: 'POST',
            signal,
            headers,
            body: JSON.stringify(payload),
        });
        if (!response.ok) throw new Error(`自定义 tagger 请求失败: HTTP ${response.status} ${await response.text()}`);
        const json = await safeReadJsonResponse(response);
        logTaggerPayload('tagger raw response', json);
        assertMangaRequestContext(requestContext);
        const normalized = validateStructuredResult(normalizeTaggerResult(json, rawLorebooks, requestContext.manga ? requestContext : null));
        logTaggerPayload('tagger normalized result', normalized);
        return normalized;
    }

    /* ── 6.5.49: 「🔍 检测工具调用」 ── */
    const TOOL_PROBE_TOOL = {
        type: 'function',
        function: {
            name: 'rbq_tool_probe',
            description: 'Connectivity check. Call this tool with answer "ok".',
            parameters: { type: 'object', properties: { answer: { type: 'string', description: 'Always "ok".' } }, required: ['answer'] },
        },
    };

    /** Pure classification of one probe outcome. verdict: 'supported' | 'unsupported' | 'error'. */
    function classifyToolProbe({ httpStatus = 200, httpText = '', toolCalls = [], content = '', thrown = null } = {}) {
        if (thrown) {
            if (thrown.name === 'AbortError') return { verdict: 'error', message: '检测超时或已取消，开关没有改动。' };
            if (thrown.code === 'SDT_TOOLS_UNSUPPORTED') {
                // callApiWithJsonFallback already retried tool_choice:'auto'. A 500 without a tools/function hint is a server fault.
                if (thrown.status !== 500 || /tool|function/i.test(String(thrown.responseText || ''))) {
                    return { verdict: 'unsupported', message: `接口拒绝了工具调用请求 (HTTP ${thrown.status || '?'})。${String(thrown.responseText || '').slice(0, 160)}` };
                }
                return { verdict: 'error', message: `接口出错 (HTTP 500)，无法判断是否支持工具调用，开关没有改动。\n${String(thrown.responseText || '').slice(0, 200)}` };
            }
            return { verdict: 'error', message: `请求失败：${thrown.message || String(thrown)}\n开关没有改动，请检查网络、地址和 Key。` };
        }
        if (httpStatus < 200 || httpStatus >= 300) {
            const text = String(httpText || '');
            if ((httpStatus === 400 || httpStatus === 422 || httpStatus === 501) && /tool|function/i.test(text)) {
                return { verdict: 'unsupported', message: `接口不接受工具调用参数 (HTTP ${httpStatus})。` };
            }
            const hint = httpStatus === 401 || httpStatus === 403 ? 'Key 无效或没有权限'
                : httpStatus === 404 ? '地址或模型名不对' : httpStatus === 429 ? '请求太频繁或额度不足' : '接口出错';
            return { verdict: 'error', message: `HTTP ${httpStatus}：${hint}。开关没有改动。\n${text.slice(0, 200)}` };
        }
        const call = (toolCalls || []).find(c => !c?.name || c.name === TOOL_PROBE_TOOL.function.name);
        if (call) {
            let args = call.arguments;
            try { args = typeof args === 'string' ? JSON.parse(args) : args; } catch (_) { args = null; }
            if (args && typeof args === 'object' && !Array.isArray(args)) return { verdict: 'supported', message: '模型按要求返回了工具调用。' };
            return { verdict: 'unsupported', message: '模型返回了工具调用，但参数不是合法 JSON。' };
        }
        const text = String(content || '').trim();
        if (!text) return { verdict: 'error', message: '接口没有返回任何内容，开关没有改动，请稍后再试。' };
        // Relays that swallow upstream failures into the text body (e.g. "[proxy error] {...}") are errors, not a verdict.
        if (isRelayErrorText(text)) {
            return { verdict: 'error', message: `中转站返回了错误：${text.slice(0, 200)}\n开关没有改动。` };
        }
        return { verdict: 'unsupported', message: `模型只回了普通文字，没有返回工具调用：「${text.slice(0, 80)}${text.length > 80 ? '…' : ''}」` };
    }

    // 6.5.58 多渠道：target 为空时用老字段（等价 6.5.57），传渠道则用渠道自己的地址/Key/模型
    async function probeToolCallSupport(store, { signal = null, fetchFn = null, target = null } = {}) {
        const url = normalizeBaseUrl((target && target.baseUrl) || store.openaiBaseUrl);
        if (!url) return { verdict: 'error', message: '请先填写 OpenAI 兼容接口 Base URL。' };
        const modelName = String((target && target.model) || '').trim() || (store.openaiModelCustom || '').trim() || store.openaiModel;
        if (!modelName) return { verdict: 'error', message: '请先选择或填写模型。' };
        try { checkUrlSafety(url); } catch (err) { return { verdict: 'error', message: err.message || String(err) }; }
        // Same shape SDT uses for real tool-mode requests: forced tool_choice, stream=true, thinking params.
        const reqBody = {
            model: modelName,
            temperature: 0,
            stream: true,
            messages: [
                { role: 'system', content: 'You are a connectivity test. Always answer by calling the rbq_tool_probe tool.' },
                { role: 'user', content: '请调用 rbq_tool_probe 工具，answer 填 "ok"。' },
            ],
            ...buildThinkingParams(store),
            tools: [TOOL_PROBE_TOOL],
            tool_choice: { type: 'function', function: { name: TOOL_PROBE_TOOL.function.name } },
        };
        let response;
        const probeApiKey = String((target && target.apiKey) || store.openaiApiKey || '').trim();
        try {
            response = await callApiWithJsonFallback(url, {
                method: 'POST',
                signal,
                headers: {
                    'Content-Type': 'application/json',
                    ...(probeApiKey ? { Authorization: `Bearer ${probeApiKey}` } : {}),
                },
            }, reqBody, fetchFn || smartFetch);
        } catch (err) {
            return classifyToolProbe({ thrown: err });
        }
        if (!response.ok) {
            let text = '';
            try { text = await response.text(); } catch (_) {}
            return classifyToolProbe({ httpStatus: response.status, httpText: text });
        }
        try {
            const ct = response.headers?.get?.('content-type') || '';
            let toolCalls = [], content = '';
            const fromEnvelope = json => {
                if (json?.error) throw Object.assign(new Error(`接口返回错误：${json.error.message || JSON.stringify(json.error)}`), { code: 'SDT_PROBE_API_ERROR' });
                toolCalls = getCompletionToolCalls(json);
                const choice = json?.choices?.[0];
                const parts = Array.isArray(json?.candidates?.[0]?.content?.parts) ? json.candidates[0].content.parts : [];
                content = choice?.message?.content ?? choice?.text ?? parts.filter(p => !p?.thought && typeof p?.text === 'string').map(p => p.text).join('');
            };
            if (response.body && typeof response.body.getReader === 'function' && (ct.includes('text/event-stream') || reqBody.stream)) {
                const { sseState, rawStreamText } = await readSseCompletion(response, signal, null, TOOL_PROBE_TOOL.function.name);
                if (!sseState.toolCalls?.length && !sseState.accumulatedArgs && !sseState.accumulatedContent && rawStreamText.trim().startsWith('{')) {
                    fromEnvelope(JSON.parse(rawStreamText.trim()));
                } else {
                    toolCalls = sseState.toolCalls?.length ? sseState.toolCalls
                        : (sseState.accumulatedArgs ? [{ name: TOOL_PROBE_TOOL.function.name, arguments: sseState.accumulatedArgs }] : []);
                    content = sseState.accumulatedContent || '';
                }
            } else {
                fromEnvelope(await safeReadJsonResponse(response));
            }
            return classifyToolProbe({ toolCalls, content });
        } catch (err) {
            return classifyToolProbe({ thrown: err });
        }
    }

    // 6.5.58 多渠道：单次执行体（渠道由外层 callStructuredCompletion 注入）
    async function callStructuredCompletionOnce({
        messages,
        tool = null,
        temperature = 0.2,
        signal = null,
        customStore = null,
        fetchFn = null,
        onProgress = null,
        _toolFallbackRetried = false,
        channel = null
    }) {
        const store = customStore || getStore();
        const channelTarget = channel || sdtPrimaryChannelTarget(store) || null;
        const url = normalizeBaseUrl(channelTarget && channelTarget.baseUrl);
        if (!url) throw new Error('请先填写 OpenAI 兼容接口 Base URL');
        const modelName = String((channelTarget && channelTarget.model) || '').trim() || (store.openaiModelCustom || '').trim() || store.openaiModel;
        if (!modelName) throw new Error('请先填写模型名称');
        const channelApiKey = String((channelTarget && channelTarget.apiKey) || store.openaiApiKey || '').trim();
        checkUrlSafety(url);

        const myFetch = fetchFn || smartFetch;

        const reqBody = {
            model: modelName,
            temperature,
            stream: false,
            messages: Array.isArray(messages) ? messages.map(m => ({ ...m })) : [],
            ...buildThinkingParams(store),
        };

        const useToolCall = !!(store.toolCallMode && tool);
        if (useToolCall) {
            reqBody.tools = [tool];
            reqBody.tool_choice = { type: 'function', function: { name: tool.function.name } };
            reqBody.stream = true; // 必须开启流式，以兼容各类中转代理对 Gemini 工具调用的特殊要求
        } else {
            reqBody.response_format = { type: 'json_object' };
            // 对 Gemini 模型，强制开启流式以避免 LiteLLM 500 Invalid non-streaming Gemini response 崩溃
            if (modelName.toLowerCase().includes('gemini')) {
                reqBody.stream = true;
            }
        }

        let response = await callApiWithJsonFallback(url, {
            method: 'POST',
            signal,
            headers: {
                'Content-Type': 'application/json',
                ...(channelApiKey ? { Authorization: `Bearer ${channelApiKey}` } : {}),
            },
        }, reqBody, myFetch);

        if (!response.ok) {
            let errText = '';
            try { errText = await response.text(); } catch (_) {}
            const err = new Error(`大模型接口请求失败 (HTTP ${response.status})`);
            err.status = response.status;
            err.rawOutput = `【HTTP 状态码】: ${response.status}\n【服务端返回原始报文】:\n${errText || '（无响应体）'}\n\n【请求地址】: ${url}\n【模型】: ${modelName}\n\n【发送的消息列表】:\n${JSON.stringify(messages, null, 2)}`;
            throw err;
        }

        const ct = response.headers.get('content-type') || '';
        const isSseStream = (ct.includes('text/event-stream') || reqBody.stream === true) && response.body && typeof response.body.getReader === 'function';

        let rawReply = '';
        let reasoning = '';
        let rawOutput = '';
        let isToolCall = false;
        let json = null;
        let sseState = null;
        const toolName = tool?.function?.name || '';
        // Some compatible endpoints return a complete legacy/native message even
        // when stream=true. Use the same envelope decoding for both body paths.
        const unwrapCompletion = envelopeJson => {
            const choice = envelopeJson?.choices?.[0];
            const message = choice?.message || choice?.delta || {};
            const parts = Array.isArray(envelopeJson?.candidates?.[0]?.content?.parts) ? envelopeJson.candidates[0].content.parts : [];
            const calls = Array.isArray(message.tool_calls) ? message.tool_calls : [];
            const call = calls.find(entry => entry?.function?.name === toolName) || calls[0];
            const nativeCalls = parts.filter(part => part?.functionCall).map(part => part.functionCall);
            const nativeCall = nativeCalls.find(entry => entry?.name === toolName) || nativeCalls[0];
            const args = call?.function?.arguments ?? message.function_call?.arguments ?? nativeCall?.args;
            const hasArgs = typeof args === 'string' || (args !== null && typeof args === 'object');
            const content = message.content ?? choice?.text ?? envelopeJson?.content
                ?? parts.filter(part => !part?.thought && typeof part?.text === 'string').map(part => part.text).join('');
            const reply = hasArgs ? args : content;
            return {
                rawReply: typeof reply === 'string' ? reply : reply && typeof reply === 'object' ? JSON.stringify(reply) : '',
                isToolCall: hasArgs,
                reasoning: message.reasoning_content || choice?.reasoning_content
                    || parts.filter(part => part?.thought).map(part => typeof part.thought === 'string' ? part.thought : part.text || '').join('')
            };
        };

        if (isSseStream) {
            const streamResult = await readSseCompletion(response, signal, onProgress, useToolCall ? toolName : '');
            sseState = streamResult.sseState;
            rawOutput = streamResult.rawStreamText;

            // 容错：如果流中未检测到 SSE 格式 (data:)，但实际上返回了完整的单体 JSON（例如反代未走流式包装）
            if (!sseState.accumulatedArgs && !sseState.accumulatedContent && !sseState.hasSafetyBlock && rawOutput.trim()) {
                const trimmedRaw = rawOutput.trim();
                if (trimmedRaw.startsWith('{') && trimmedRaw.endsWith('}')) {
                    try {
                        const parsedDirect = JSON.parse(trimmedRaw);
                        if (parsedDirect && (parsedDirect.choices || parsedDirect.candidates || parsedDirect.error || parsedDirect.promptFeedback)) {
                            json = parsedDirect;
                            ({ rawReply, reasoning, isToolCall } = unwrapCompletion(parsedDirect));
                        }
                    } catch (_e) {}
                }
            }

            if (!rawReply) {
                if (sseState.accumulatedArgs) {
                    isToolCall = true;
                    rawReply = sseState.accumulatedArgs;
                } else if (sseState.accumulatedContent) {
                    rawReply = sseState.accumulatedContent;
                } else if (sseState.accumulatedReasoning) {
                    rawReply = sseState.accumulatedReasoning;
                }
                reasoning = sseState.accumulatedReasoning;

                const isSafetyReason = sseState.hasSafetyBlock
                    || (sseState.lastFinishReason && /content_filter|safety|prohibited|recitation|blocklist|spii/i.test(sseState.lastFinishReason));
                if (!rawReply && isSafetyReason) {
                    const safetyDetail = sseState.safetyReason || `finish_reason: ${sseState.lastFinishReason}`;
                    const err = new Error(`大模型触发了官方前置内容安全审查 (${safetyDetail})`);
                    err.rawOutput = `【前置安全审查熔断】: ${safetyDetail}\n\n【请求地址与模型】:\n- Endpoint: ${url}\n- Model: ${modelName}\n\n【调试信息】:\n${JSON.stringify(sseState.rawDebugChunks, null, 2)}\n\n【发送的消息列表】:\n${JSON.stringify(messages, null, 2)}`;
                    throw err;
                }
            }
        } else {
            // 非流式响应
            const jsonText = await response.text();
            rawOutput = jsonText;
            try {
                json = JSON.parse(jsonText);
            } catch (_e) {
                rawReply = jsonText;
            }
            if (json) {
                ({ rawReply, reasoning, isToolCall } = unwrapCompletion(json));
            }
        }

        if (json?.error) {
            const err = new Error(`大模型返回错误: ${json.error.message || JSON.stringify(json.error)}`);
            err.rawOutput = `【服务端返回错误对象】:\n${JSON.stringify(json, null, 2)}\n\n【请求地址与模型】:\n- Endpoint: ${url}\n- Model: ${modelName}\n\n【发送的消息列表】:\n${JSON.stringify(messages, null, 2)}`;
            throw err;
        }

        if (useToolCall) {
            // A partial tool payload is not a successful completion when the
            // provider reports a blocked or truncated response.
            const finishReason = json?.choices?.[0]?.finish_reason || json?.candidates?.[0]?.finishReason || sseState?.lastFinishReason;
            const blockReason = json?.promptFeedback?.blockReason;
            const refusal = json?.choices?.[0]?.message?.refusal || json?.candidates?.[0]?.refusal;
            if (sseState?.hasSafetyBlock || blockReason || (typeof refusal === 'string' && refusal.trim())
                || /content_filter|safety|prohibited|recitation|blocklist|spii/i.test(String(finishReason || ''))) {
                const detail = sseState?.safetyReason || blockReason || (refusal ? 'refusal' : finishReason);
                const err = new Error(`大模型返回内容安全拦截 (${detail})，未采用工具参数`);
                err.code = 'SDT_TOOL_RESPONSE_BLOCKED';
                err.rawOutput = rawOutput;
                throw err;
            }
            if (/^(?:length|max_tokens)$/i.test(String(finishReason || ''))) {
                const err = new Error('大模型工具参数因达到输出 Token 上限而被截断，请减少上下文或增加输出额度');
                err.code = 'SDT_TOOL_RESPONSE_TRUNCATED';
                err.rawOutput = rawOutput;
                throw err;
            }
            try {
                const call = selectCompletionToolCall(json ? getCompletionToolCalls(json) : sseState?.toolCalls, toolName);
                if (call) {
                    validateCompletionToolArguments(call.arguments, tool);
                    isToolCall = true;
                    rawReply = typeof call.arguments === 'string' ? call.arguments : JSON.stringify(call.arguments);
                }
            } catch (err) {
                err.rawOutput = rawOutput;
                throw err;
            }
            if (!isToolCall || !rawReply) {
                // 6.5.49: 正文里带了参数（含中转模拟的 <<TOOL_CALL>> 文本）就直接采用；否则去掉 tools 普通 JSON 重试一次。
                const recovered = recoverToolArgumentsFromText([rawReply, reasoning, sseState?.accumulatedContent], tool);
                if (recovered) {
                    console.info(`[${PLUGIN_NAME}] 模型未返回 tool_calls，已从正文中解析出 ${toolName} 参数并采用`);
                    isToolCall = true;
                    rawReply = JSON.stringify(recovered);
                } else {
                    const relayError = [rawReply, sseState?.accumulatedContent].find(isRelayErrorText);
                    if (relayError) throw makeRelayErrorTextError(relayError);
                    if (signal?.aborted) {
                        throw signal.reason && typeof signal.reason.message === 'string'
                            ? signal.reason : Object.assign(new Error('大模型请求已取消'), { name: 'AbortError' });
                    }
                    if (_toolFallbackRetried) throw makeToolFallbackError(finishReason, rawReply || rawOutput, true);
                    console.warn(`[${PLUGIN_NAME}] ⚠️ 模型未返回 ${toolName} 工具调用参数${finishReason ? ` (finish_reason: ${finishReason})` : ''}，自动去掉 tools 改用普通 JSON 模式重试一次`);
                    if (typeof toastr !== 'undefined' && typeof toastr.info === 'function') toastr.info('模型没按工具调用返回，已自动改用普通模式重试', PLUGIN_NAME);
                    const schemaText = (() => { try { return JSON.stringify(tool?.function?.parameters || {}); } catch (_) { return '{}'; } })();
                    const formatNote = `[输出格式] 不要调用任何工具/函数。直接只输出一个 JSON 对象（不要代码块、不要解释），它就是 ${toolName} 工具的参数，结构遵循此 JSON Schema：${schemaText}`;
                    const retryMessages = (Array.isArray(messages) ? messages : []).map(m => ({ ...m }));
                    const lastUser = [...retryMessages].reverse().find(m => m.role === 'user' && typeof m.content === 'string');
                    if (lastUser) lastUser.content += `\n\n${formatNote}`;
                    else retryMessages.push({ role: 'user', content: formatNote });
                    let retry;
                    try {
                        retry = await callStructuredCompletionOnce({
                            messages: retryMessages, tool, temperature, signal, fetchFn, onProgress, channel,
                            customStore: { ...store, toolCallMode: false }, _toolFallbackRetried: true,
                        });
                    } catch (retryErr) {
                        if (retryErr?.name === 'AbortError' || signal?.aborted) throw retryErr;
                        const err = makeToolFallbackError(finishReason, rawReply || rawOutput, true);
                        err.retryError = retryErr;
                        err.rawOutput += `\n\n【普通 JSON 模式重试的错误】: ${retryErr?.message || String(retryErr)}`;
                        throw err;
                    }
                    const retryArgs = recoverToolArgumentsFromText([retry.rawReply, retry.reasoning], tool);
                    if (retryArgs) return { ...retry, rawReply: JSON.stringify(retryArgs), isToolCall: true, toolName };
                    let parsedRetry = {};
                    try { parsedRetry = extractJson(retry.rawReply); } catch (_) {}
                    if (!parsedRetry || typeof parsedRetry !== 'object' || !Object.keys(parsedRetry).length) {
                        const err = makeToolFallbackError(finishReason, rawReply || rawOutput, true);
                        err.rawOutput += `\n\n【普通 JSON 模式重试的返回】:\n${retry.rawOutput || retry.rawReply || '（空）'}`;
                        throw err;
                    }
                    // Let the caller's own parser report schema-level problems (more specific than ours).
                    return { ...retry, toolName };
                }
            }
        }

        return {
            rawReply: String(rawReply || '').trim(),
            rawOutput,
            reasoning,
            isToolCall,
            toolName,
            model: modelName,
            endpoint: url
        };
    }

    // 6.5.58 多渠道：工具调用 / 普通 JSON 都按渠道链切换；单渠道时与 6.5.57 等价
    async function callStructuredCompletion(options) {
        const opts = options || {};
        const store = opts.customStore || getStore();
        const useTool = !!store.toolCallMode && !!opts.tool;
        return await sdtWithChannelChain(store, '大模型结构化调用', async function (target) {
            return await callStructuredCompletionOnce(Object.assign({}, opts, { channel: target }));
        }, { signal: opts.signal, toolCall: useTool });
    }

    async function callDrawSpecCompletion(messages, store, promptBundle = null, taskInput = null, requestTool = null) {
        const completion = await callStructuredCompletion({
            messages,
            tool: requestTool || getDrawSpecTool(store, promptBundle, taskInput),
            customStore: store,
        });
        // Keep the existing normalizer's tool extraction and diagnostic fields.
        return {
            choices: [{ message: {
                content: completion.isToolCall ? null : completion.rawReply,
                reasoning_content: completion.reasoning,
                ...(completion.isToolCall ? { tool_calls: [{ type: 'function', function: {
                    name: completion.toolName,
                    arguments: completion.rawReply,
                } }] } : {}),
            } }],
        };
    }

    async function callTagger(messageId, trigger, { signal } = {}) {
        const liveStore = getStore();
        const promptSnapshot = liveStore.enhancedContext === 'v_manga_layered_v1'
            ? captureLayeredMangaPromptSnapshot(liveStore) : null;
        const store = promptSnapshot?.storeSnapshot || liveStore;
        const origin = captureMangaRequestContext(null, messageId, promptSnapshot);
        if (store.lorebookEnabled) {
            try { await warmLorebookMemoryCache(); } catch (_e) {}
        }
        assertMangaRequestContext(origin);
        return store.provider === 'custom'
            ? callCustomHttp(messageId, trigger, { signal, promptSnapshot })
            : callOpenAiCompatible(messageId, trigger, { signal, promptSnapshot });
    }

    function visibleTextNodes(root) {
        const nodes = [];
        const ignoredSelector = [
            `.${CARD_CLASS}`,
            '.st-scene-trigger-inline-wrap',
            'script',
            'style',
            '.mes_timer',
            '.mes_reasoning',
            '.mes_reasoning_header',
            '.mes_reasoning_details',
            '.mes_reasoning_summary',
            'summary',
            'details',
            '[data-role="message-reasoning"]',
            '.thinking-block',
            '.thought',
            '.mes_buttons',
            '.mes_edit_buttons',
            '.mes_img_controls',
            '[data-role="message-actions"]',
            '[data-role="message-metadata"]'
        ].join(', ');
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
            acceptNode(node) {
                if (!node.nodeValue) return NodeFilter.FILTER_REJECT;
                const parent = node.parentElement;
                if (!parent) return NodeFilter.FILTER_REJECT;
                if (parent.closest(ignoredSelector)) return NodeFilter.FILTER_REJECT;
                return NodeFilter.FILTER_ACCEPT;
            }
        });
        while (walker.nextNode()) nodes.push(walker.currentNode);
        return nodes;
    }

    function getPureMessageRoot(messageId) {
        const container = RBQ.api.getMessageTextContainer(messageId);
        if (!(container instanceof HTMLElement)) return null;
        const clone = container.cloneNode(true);
        if (!(clone instanceof HTMLElement)) return null;

        clone.querySelectorAll([
            '.mes_timer',
            '.mes_reasoning',
            '.mes_reasoning_header',
            '.mes_reasoning_details',
            '.mes_reasoning_summary',
            'summary',
            'details',
            '.st-scene-trigger-inline-wrap',
            `.${CARD_CLASS}`,
            '.mes_buttons',
            '.mes_edit_buttons',
            '.mes_img_controls',
            '[data-role="message-actions"]',
            '[data-role="message-metadata"]'
        ].join(',')).forEach(node => node.remove());

        return clone;
    }

    function buildSentenceMapFromRoot(root) {
        if (!(root instanceof HTMLElement)) return [];
        const sentenceRegex = /[^。！？.!?\n]+[。！？.!?]?/g;
        const map = [];
        let sentenceIndex = 0;
        for (const node of visibleTextNodes(root)) {
            const text = node.nodeValue || '';
            let match;
            while ((match = sentenceRegex.exec(text))) {
                const sentence = String(match[0] || '').trim();
                if (!sentence) continue;
                sentenceIndex += 1;
                map.push({
                    sentenceIndex,
                    text: sentence,
                    node,
                    startOffset: match.index,
                    endOffset: match.index + match[0].length,
                });
            }
        }
        return map;
    }

    function buildSentenceMap(messageId) {
        const root = getPureMessageRoot(messageId);
        return buildSentenceMapFromRoot(root);
    }

    function getLivePureMessageRoot(messageId) {
        const container = RBQ.api.getMessageTextContainer(messageId);
        if (!(container instanceof HTMLElement)) return null;
        const clone = container.cloneNode(true);
        if (!(clone instanceof HTMLElement)) return null;

        clone.querySelectorAll([
            '.mes_timer',
            '.mes_reasoning',
            '.mes_reasoning_header',
            '.mes_reasoning_details',
            '.mes_reasoning_summary',
            'summary',
            'details',
            '.st-scene-trigger-inline-wrap',
            `.${CARD_CLASS}`,
            '.mes_buttons',
            '.mes_edit_buttons',
            '.mes_img_controls',
            '[data-role="message-actions"]',
            '[data-role="message-metadata"]'
        ].join(',')).forEach(node => node.remove());

        return clone;
    }

    function insertWrapperAtTextNode(node, start, end, wrapper) {
        const text = node.nodeValue || '';
        const fragment = document.createDocumentFragment();
        if (start > 0) fragment.append(document.createTextNode(text.slice(0, start)));
        fragment.append(wrapper);
        if (end < text.length) fragment.append(document.createTextNode(text.slice(end)));
        node.parentNode.replaceChild(fragment, node);
    }

    function insertAtMarker(container, marker, wrapper) {
        for (const node of visibleTextNodes(container)) {
            const text = node.nodeValue || '';
            const index = text.indexOf(marker);
            if (index >= 0) {
                insertWrapperAtTextNode(node, index, index + marker.length, wrapper);
                return true;
            }
        }
        return false;
    }

    function insertAfterSentence(container, sentenceIndex, wrapper) {
        const targetIndex = Math.max(1, Number(sentenceIndex) || 1);
        let seen = 0;
        const sentenceRegex = /[^。！？.!?\n]+[。！？.!?]?/g;
        for (const node of visibleTextNodes(container)) {
            const text = node.nodeValue || '';
            let match;
            while ((match = sentenceRegex.exec(text))) {
                if (!match[0].trim()) continue;
                seen += 1;
                if (seen === targetIndex) {
                    const insertAt = match.index + match[0].length;
                    insertWrapperAtTextNode(node, insertAt, insertAt, wrapper);
                    return true;
                }
            }
        }
        return false;
    }

    function insertBySentenceMap(messageId, anchor, wrapper) {
        const container = RBQ.api.getMessageTextContainer(messageId);
        if (!(container instanceof HTMLElement)) return false;

        // Strategy 1: Direct text search — handles cross-sentence anchors and inline elements
        if (anchor?.text) {
            const inserted = insertByDirectTextSearch(container, anchor.text, wrapper);
            if (inserted) return true;
        }

        // Strategy 2: Fall back to sentence map by text overlap if direct text search didn't match
        if (anchor?.text) {
            const map = buildSentenceMapFromRoot(container);
            if (map.length > 0) {
                let bestEntry = null;
                let maxOverlap = 0;
                const cleanAnchor = cleanTextForMatch(anchor.text);
                for (const entry of map) {
                    const cleanSent = cleanTextForMatch(entry.sentence);
                    if (!cleanSent) continue;
                    let overlap = 0;
                    if (cleanSent.includes(cleanAnchor) || cleanAnchor.includes(cleanSent)) {
                        overlap = Math.min(cleanAnchor.length, cleanSent.length) * 2;
                    } else {
                        for (let len = Math.min(cleanAnchor.length, cleanSent.length); len >= 4; len--) {
                            for (let s = 0; s <= cleanAnchor.length - len; s++) {
                                if (cleanSent.includes(cleanAnchor.slice(s, s + len))) {
                                    overlap = len;
                                    break;
                                }
                            }
                            if (overlap > 0) break;
                        }
                    }
                    if (overlap > maxOverlap) {
                        maxOverlap = overlap;
                        bestEntry = entry;
                    }
                }
                if (bestEntry && maxOverlap >= 4) {
                    insertWrapperAtTextNode(bestEntry.node, bestEntry.endOffset, bestEntry.endOffset, wrapper);
                    return true;
                }
            }
        }

        // Strategy 3: Fall back to sentence index ONLY if an explicit valid index was supplied
        const explicitIndex = Number(anchor?.index);
        if (Number.isFinite(explicitIndex) && explicitIndex > 0) {
            const map = buildSentenceMapFromRoot(container);
            const matched = map.find((entry) => entry.sentenceIndex === explicitIndex) || null;
            if (matched) {
                insertWrapperAtTextNode(matched.node, matched.endOffset, matched.endOffset, wrapper);
                return true;
            }
        }
        return false;
    }

    /**
     * Search for anchorText directly in the concatenated visible text of the container,
     * then insert the wrapper right after where the anchor text ends.
     * This avoids sentence-boundary issues entirely.
     */
    function insertByDirectTextSearch(container, anchorText, wrapper) {
        const nodes = visibleTextNodes(container);
        if (!nodes.length) return false;

        const needle = String(anchorText || '').trim();
        if (needle.length < 4) return false;

        // Build concatenated text with node offset mapping
        const nodeMap = []; // { node, startInFull, length }
        let fullText = '';
        for (const node of nodes) {
            const text = node.nodeValue || '';
            nodeMap.push({ node, startInFull: fullText.length, length: text.length });
            fullText += text;
        }

        // Find the end position of the anchor text in the full text
        let matchEnd = findAnchorEndPosition(fullText, needle);
        if (matchEnd < 0) return false;

        // Map global end position back to a text node + local offset
        for (const entry of nodeMap) {
            const nodeEnd = entry.startInFull + entry.length;
            if (matchEnd <= nodeEnd) {
                const localOffset = matchEnd - entry.startInFull;
                insertWrapperAtTextNode(entry.node, localOffset, localOffset, wrapper);
                return true;
            }
        }
        return false;
    }

    function findAnchorEndPosition(fullText, needle) {
        if (!fullText || !needle) return -1;

        // 1. Exact raw substring match
        const idx = fullText.indexOf(needle);
        if (idx >= 0) return idx + needle.length;

        // 2. Whitespace-normalized raw match (handles minor spacing differences)
        const normFull = fullText.toLowerCase().replace(/\s+/g, '');
        const normNeedle = needle.toLowerCase().replace(/\s+/g, '');
        const normIdx = normFull.indexOf(normNeedle);
        if (normIdx >= 0) {
            // Map normalized end position back to original text position
            const normEnd = normIdx + normNeedle.length;
            let normPos = 0;
            for (let i = 0; i < fullText.length; i++) {
                if (!/\s/.test(fullText[i].toLowerCase())) normPos++;
                if (normPos >= normEnd) return i + 1;
            }
        }

        // 3. Cleaned text exact match (Markdown syntax stripped, quotes & punctuation normalized)
        const { cleanStr, cleanToFullEndIndex } = buildCleanMap(fullText);
        const cleanNeedle = cleanTextForMatch(needle);
        if (!cleanStr || !cleanNeedle) return -1;

        const cleanIdx = cleanStr.indexOf(cleanNeedle);
        if (cleanIdx >= 0) {
            const cleanEnd = cleanIdx + cleanNeedle.length - 1;
            if (cleanEnd < cleanToFullEndIndex.length) {
                return cleanToFullEndIndex[cleanEnd];
            }
        }

        // 4. Cleaned text fuzzy match: find the longest matching slice (suffix, prefix, or sliding window)
        const minLen = Math.max(4, Math.floor(cleanNeedle.length * 0.4));
        for (let len = cleanNeedle.length - 1; len >= minLen; len--) {
            // Check suffix first (most common: LLM anchor matched end of sentence)
            const suffix = cleanNeedle.slice(cleanNeedle.length - len);
            const suffixIdx = cleanStr.indexOf(suffix);
            if (suffixIdx >= 0) {
                const cleanEnd = suffixIdx + suffix.length - 1;
                if (cleanEnd < cleanToFullEndIndex.length) {
                    return cleanToFullEndIndex[cleanEnd];
                }
            }

            // Check prefix (LLM anchor matched beginning of sentence)
            const prefix = cleanNeedle.slice(0, len);
            const prefixIdx = cleanStr.indexOf(prefix);
            if (prefixIdx >= 0) {
                const cleanEnd = prefixIdx + prefix.length - 1;
                if (cleanEnd < cleanToFullEndIndex.length) {
                    return cleanToFullEndIndex[cleanEnd];
                }
            }

            // Sliding window: internal substring match
            for (let s = 1; s <= cleanNeedle.length - len - 1; s++) {
                const sub = cleanNeedle.slice(s, s + len);
                const subIdx = cleanStr.indexOf(sub);
                if (subIdx >= 0) {
                    const cleanEnd = subIdx + sub.length - 1;
                    if (cleanEnd < cleanToFullEndIndex.length) {
                        return cleanToFullEndIndex[cleanEnd];
                    }
                }
            }
        }

        return -1;
    }

    function injectMessageActionButton(messageId, wrapper, trigger, key) {
        return syncMessageActionButton(messageId, wrapper, trigger, key);
    }

    function syncMessageActionButton(messageId, wrapper, trigger, key) {
        try {
            const store = getStore();
            const mesEl = document.querySelector(`.mes[mesid="${messageId}"]`);
            if (!mesEl) return;
            const btnBar = mesEl.querySelector('.extraMesButtons') || mesEl.querySelector('.mes_buttons') || mesEl.querySelector('.flex-container');
            if (!btnBar) {
                // 如果操作栏 DOM 尚未渲染完成，延迟重试挂载，防止消息操作栏小图标模式下按钮永久消失
                if (store.cardPosition === 'message_actions') {
                    setTimeout(() => syncMessageActionButton(messageId, wrapper, trigger, key), 300);
                }
                return;
            }
            let existing = btnBar.querySelector(`.rbq-sdt-action-btn`);

            // 如果当前不是「消息操作栏小图标」模式，坚决清理移除该按钮，绝不常驻干扰
            if (store.cardPosition !== 'message_actions') {
                if (existing) existing.remove();
                return;
            }

            // 仅在「消息操作栏小图标」模式下挂载按钮
            if (!existing) {
                const btn = document.createElement('div');
                btn.className = 'mes_button extra_mes_button rbq-sdt-action-btn';
                btn.title = '智能生图 / 解析分镜 (纯净免占位)';
                btn.innerHTML = '<i class="fa-solid fa-camera" style="color:#38bdf8"></i>';
                btn.style.cursor = 'pointer';
                btn.style.display = 'inline-flex';
                btn.style.alignItems = 'center';
                btn.style.justifyContent = 'center';
                btn.style.margin = '0 2px';
                btn.addEventListener('click', async (e) => {
                    e.stopPropagation();
                    const msgSnapshot = getMessageSnapshot(messageId);
                    const effectiveTrigger = trigger || getTrigger(msgSnapshot);
                    const curKey = key || (effectiveTrigger ? makeKey(messageId, msgSnapshot, effectiveTrigger.type, effectiveTrigger.marker || 'auto') : '');
                    if (!curKey || inFlight.has(curKey)) {
                        toastr.info('当前分镜正在解析中，请稍候...', PLUGIN_NAME);
                        return;
                    }
                    const icon = btn.querySelector('i');
                    if (icon) {
                        icon.className = 'fa-solid fa-spinner fa-spin';
                        icon.style.color = '#38bdf8';
                    }
                    toastr.info('正在调用 tagger API 解析分镜与提示词...', PLUGIN_NAME);
                    try {
                        const placeholder = {
                            shouldDraw: true,
                            prompt: effectiveTrigger?.marker || '[Smart Draw]',
                            negative: '',
                            anchor: { type: 'bottom' },
                            reason: '正在调用 tagger API 解析世界书与提示词...',
                            multiChar: false,
                            scene: '',
                            characters: [],
                        };
                        const detachedWrapper = createConfiguredCard({
                            messageId,
                            trigger: effectiveTrigger,
                            result: placeholder,
                            key: curKey,
                            baseKey: curKey,
                            isResult: false,
                        });
                        inFlight.add(curKey);
                        await runTaggerForWrapper(detachedWrapper, effectiveTrigger, messageId, curKey);
                    } catch (err) {
                        console.error(`[${PLUGIN_NAME}] action button tagger error:`, err);
                    } finally {
                        inFlight.delete(curKey);
                        if (icon) {
                            icon.className = 'fa-solid fa-camera';
                            icon.style.color = '#38bdf8';
                        }
                    }
                });
                btnBar.appendChild(btn);
            }
        } catch (_e) { /* noop */ }
    }

    function createConfiguredCard({
        messageId,
        trigger,
        result,
        key,
        baseKey = null,
        segmentIndex = null,
        isResult = true,
    }) {
        const finalPrompt = getFinalPrompt(result);

        const wrapper = RBQ.api.createPromptCard({
            messageId,
            prompt: finalPrompt || trigger?.marker || '[Smart Draw]',
            raw: trigger?.marker || '[Smart Draw]',
            id: `smart-draw:${key}`,
            label: 'smart-draw',
        });
        if (!(wrapper instanceof HTMLElement)) return null;
        wrapper.classList.add(CARD_CLASS);

        // Hide host extension's default "生成图片" button — we use our own
        const hostButton = wrapper.querySelector('.st-scene-trigger-generate:not(.rbq-sdt-run-image)');
        if (hostButton) hostButton.style.display = 'none';

        wrapper.dataset.messageId = String(messageId);
        wrapper.dataset.rbqSdtTrigger = JSON.stringify(trigger || {});
        wrapper.dataset.rbqSdtKey = key;
        wrapper.dataset.rbqSdtBaseKey = baseKey || key;
        wrapper.dataset.rbqSdtSegmentKey = key;
        if (segmentIndex != null) wrapper.dataset.rbqSdtSegmentIndex = String(segmentIndex);
        wrapper.dataset.rbqSdtIsResult = isResult ? '1' : '0';
        wrapper.dataset.rbqSdtTriggerType = trigger?.type || 'auto';
        wrapper.dataset.rbqSdtReason = result.reason || '';
        wrapper.dataset.rbqSdtFinalPrompt = finalPrompt;
        if (result) {
            const segLabel = getSegmentLabel(result, '').trim();
            if (segLabel && segLabel !== '生成图片') {
                wrapper.dataset.rbqSdtOrigLabel = segLabel;
            }
        }

        // Store structured char data for NAI V4 direct injection on manual generate
        cacheWrapperCharacterData(wrapper, result);

        renderCardBadges(wrapper, result);
        return wrapper;
    }

    function tryMountAnchoredCard(container, messageId, trigger, result, wrapper) {
        if (trigger?.type === 'marker' && trigger.marker) {
            return insertAtMarker(container, trigger.marker, wrapper);
        } else if (result?.anchor?.text || (Number.isFinite(Number(result?.anchor?.index)) && Number(result?.anchor?.index) > 0)) {
            return insertBySentenceMap(messageId, result.anchor, wrapper);
        }
        return false;
    }

    function mountFallbackFragment(container, fragment, store = null, isResultCard = false) {
        if (!container || !fragment || !fragment.hasChildNodes()) return;
        const currentStore = store || getStore();
        // 关键保护：若为生图结果/分镜卡片，即使兜底未命中锚点，也绝对不置顶到消息开头（防止大卡片遮挡正文与产生未匹配感），一律平滑追加到正文末尾；
        // 只有未解析前的初始占位大卡片（!isResultCard），才遵循 cardPosition === 'top' 放置在开头。
        if (!isResultCard && currentStore.cardPosition === 'top') {
            const reasoningEl = container.querySelector('.mes_reasoning, details, .thinking-block, .thought');
            const headerEl = container.querySelector('.mes_header, .extraMesButtons, .mes_buttons, .timestamp, .mes_title');
            if (reasoningEl && reasoningEl.nextSibling) {
                container.insertBefore(fragment, reasoningEl.nextSibling);
            } else if (reasoningEl) {
                // 有思考块但暂无后续正文节点时，插入到思考块之后，绝不挂载到思考中上方
                reasoningEl.insertAdjacentElement('afterend', fragment.firstElementChild);
                if (fragment.hasChildNodes()) container.append(fragment);
            } else if (headerEl && headerEl.nextSibling) {
                container.insertBefore(fragment, headerEl.nextSibling);
            } else {
                container.prepend(fragment);
            }
        } else {
            container.append(fragment);
        }
    }

    function insertCard(messageId, trigger, result, key, baseKey = null, configureWrapper = null) {
        const container = RBQ.api.getMessageTextContainer(messageId);
        if (!(container instanceof HTMLElement)) return null;
        // 防跨楼层错位校验：确认目标容器真实属于当前 messageId
        const containerMes = container.closest('.mes[mesid]');
        if (containerMes && Number(containerMes.getAttribute('mesid')) !== Number(messageId)) {
            console.warn(`[${PLUGIN_NAME}] ❌ 拦截跨楼层错位插入: target mesId #${messageId} vs container #${containerMes.getAttribute('mesid')}`);
            return null;
        }
        const existing = container.querySelector(`[data-rbq-sdt-key="${CSS.escape(key)}"]`);
        if (existing instanceof HTMLElement) return existing;

        const store = getStore();
        const wrapper = createConfiguredCard({
            messageId,
            trigger,
            result,
            key,
            baseKey: baseKey || key,
            isResult: false,
        });
        if (!(wrapper instanceof HTMLElement)) return null;

        if (typeof configureWrapper === 'function') {
            configureWrapper(wrapper);
        }

        const isResult = !!(result?.isResult || (result?.prompt && result?.prompt !== '[Smart Draw]' && result?.shouldDraw));
        const mounted = tryMountAnchoredCard(container, messageId, trigger, result, wrapper);
        if (!mounted) {
            const fragment = document.createDocumentFragment();
            fragment.append(wrapper);
            mountFallbackFragment(container, fragment, store, isResult);
        }

        syncMessageActionButton(messageId, wrapper, trigger, key);
        debugInfo(`insertCard => #${messageId} (${key}) [${trigger?.type || 'auto'}]`);
        return wrapper;
    }

    function getSmartDrawCards(container) {
        if (!(container instanceof HTMLElement)) return [];
        return Array.from(container.querySelectorAll(`.${CARD_CLASS}`)).filter(card => card instanceof HTMLElement);
    }

    function isCardForBaseKey(card, baseKey) {
        if (!(card instanceof HTMLElement) || !baseKey) return false;
        const cardBaseKey = String(card.dataset.rbqSdtBaseKey || '').trim();
        if (cardBaseKey) return cardBaseKey === baseKey;
        const cardKey = String(card.dataset.rbqSdtKey || '').trim();
        return cardKey === baseKey || cardKey.startsWith(`${baseKey}-`);
    }

    function hasCardsForBaseKey(container, baseKey) {
        return getSmartDrawCards(container).some(card => isCardForBaseKey(card, baseKey));
    }

    function removeStaleCards(container, baseKey) {
        let removed = 0;
        for (const card of getSmartDrawCards(container)) {
            if (isCardForBaseKey(card, baseKey)) continue;
            // Don't remove cards with an active tagger running
            if (card._taggerAbort || card.dataset?.rbqSdtStage === 'parsing') continue;

            const cardKey = String(card.dataset.rbqSdtKey || card.dataset.rbqSdtBaseKey || '').trim();
            if (cardKey && baseKey) {
                const cardChat = cardKey.split(':')[0];
                const curChat = baseKey.split(':')[0];
                // 若所属会话根本不同，说明是开新对话或换卡时残留的旧会话卡片，必须立刻销毁！
                if (cardChat !== curChat) {
                    card.remove();
                    removed += 1;
                    continue;
                }
            }

            // 保留已实际生成出图的卡片（防止误删历史已有图）；对于未出图的过期结果卡片，必须彻底销毁，杜绝堆叠
            const hasImage = !!card.querySelector?.('.st-scene-trigger-inline-result img, .st-scene-trigger-inline-result video') || card.dataset?.rbqSdtStage === 'generated';
            if (hasImage) continue;
            card.remove();
            removed += 1;
        }
        return removed;
    }

    function setWrapperLoading(wrapper, text) {
        const button = wrapper?.querySelector?.('.st-scene-trigger-generate');
        const loader = wrapper?.querySelector?.('.st-scene-trigger-inline-loader');
        if (button instanceof HTMLElement) button.style.display = 'none';
        if (loader instanceof HTMLElement) {
            loader.style.display = 'flex';
            const sub = loader.querySelector('.st-scene-trigger-nai-loader-sub');
            if (sub instanceof HTMLElement) sub.textContent = text || '智能触发器正在生成图片...';
        }
    }

    function clearWrapperLoading(wrapper) {
        const button = wrapper?.querySelector?.('.st-scene-trigger-generate');
        const loader = wrapper?.querySelector?.('.st-scene-trigger-inline-loader');
        if (loader instanceof HTMLElement) loader.style.display = 'none';
        if (button instanceof HTMLElement && wrapper?.dataset?.rbqSdtIsResult !== '1') {
            button.style.display = '';
        }
    }

    function ensureTaggerButtonState(wrapper, text = '开始解析/生成 tag') {
        const button = wrapper?.querySelector?.('.st-scene-trigger-generate');
        if (!(button instanceof HTMLButtonElement)) return null;
        button.style.display = '';
        button.disabled = false;
        button.textContent = text;
        return button;
    }

    function ensureRenderGenerateButton(wrapper) {
        if (!(wrapper instanceof HTMLElement)) return null;
        let button = wrapper.querySelector('.rbq-sdt-run-image');
        if (button instanceof HTMLButtonElement) return button;
        const ui = wrapper.querySelector('.st-scene-trigger-inline-ui');
        if (!(ui instanceof HTMLElement)) return null;
        button = document.createElement('button');
        button.type = 'button';
        button.className = 'menu_button st-scene-trigger-inline-button rbq-sdt-run-image';
        button.textContent = '生成图片';
        button.style.display = 'none';
        const loader = ui.querySelector('.st-scene-trigger-inline-loader');
        if (loader) ui.insertBefore(button, loader);
        else ui.append(button);
        return button;
    }

    /** Generate a descriptive label for a segment's generate button */
    function getSegmentLabel(seg, prefix = '🎨') {
        const p = prefix ? `${prefix} ` : '';
        if (!seg) return `${p}生成图片`.trim();

        // 1. LLM 输出的 label 字段（首选分镜标签）
        if (seg.label) {
            const l = String(seg.label).trim().replace(/[\r\n]+/g, ' ');
            if (l.length > 0) {
                return `${p}${l.length > 40 ? l.slice(0, 39) + '…' : l}`.trim();
            }
        }

        // 2. 备用字段 title / name (若模型输出结构变异)
        const altTitle = String(seg.title || (typeof seg.name === 'string' ? seg.name : '') || '').trim().replace(/[\r\n]+/g, ' ');
        if (altTitle.length > 0) {
            return `${p}${altTitle.length > 40 ? altTitle.slice(0, 39) + '…' : altTitle}`.trim();
        }

        // 3. 角色名拼接 (如 苏婉儿 或 角色A·角色B)
        if (Array.isArray(seg.characters) && seg.characters.length > 0) {
            const names = seg.characters.map(c => c._rawName || c.name || c.char_name).filter(Boolean);
            if (names.length) {
                const joined = names.join('·');
                return `${p}${joined.length > 40 ? joined.slice(0, 39) + '…' : joined}`.trim();
            }
        }

        // 4. 正文锚点原文提炼（提取前 10~14 字精简画面动作）
        if (seg.anchor?.text) {
            const a = String(seg.anchor.text).trim().replace(/^[“"「『\s]+/, '').replace(/[”"」』\s]+$/, '');
            if (a.length >= 2) {
                const cleanA = a.length > 14 ? a.slice(0, 13) + '…' : a;
                return `${p}${cleanA}`.trim();
            }
        }

        // 5. 分镜序号兜底（如 🎨 分镜01·剧情画面）
        const segIdx = Number(seg.segmentIndex || seg.index);
        if (Number.isFinite(segIdx) && segIdx > 0) {
            return `${p}分镜${String(segIdx).padStart(2, '0')}·剧情画面`.trim();
        }

        return `${p}生成图片`.trim();
    }

    function setGenerateButtonState(wrapper, visible, text = '生成图片', disabled = false) {
        const button = ensureRenderGenerateButton(wrapper);
        if (!(button instanceof HTMLButtonElement)) return null;
        button.style.display = visible ? '' : 'none';
        let span = button.querySelector('.st-scene-trigger-inline-btn-text');
        if (!span) {
            button.innerHTML = '<span class="st-scene-trigger-inline-btn-text"></span>';
            span = button.querySelector('.st-scene-trigger-inline-btn-text');
        }
        if (span) span.textContent = text;
        else button.textContent = text;
        button.title = text; // 设置原生提示框，鼠标悬停或长按即可查看完整分镜/角色文本
        // Save non-transient labels so getRegenLabel can read the original label
        const TRANSIENT_LABELS = ['生成中...', '自动生成中...', '等待自动生图...'];
        if (!TRANSIENT_LABELS.includes(text) && !disabled) {
            wrapper.dataset.rbqSdtOrigLabel = text.replace(/^[\u{1F300}-\u{1FAD6}\u{2600}-\u{27BF}\u{FE00}-\u{FE0F}\u{1F900}-\u{1F9FF}\u{1FA70}-\u{1FAFF}\s]+/gu, '').trim();
        }
        button.disabled = !!disabled;
        return button;
    }

    /** Swap the leading emoji to 🔄 using the stored original label */
    function getRegenLabel(wrapper) {
        const orig = wrapper?.dataset?.rbqSdtOrigLabel || '生成图片';
        return '🔄 ' + orig;
    }

    function setWrapperStage(wrapper, stage) {
        if (!(wrapper instanceof HTMLElement)) return;
        wrapper.dataset.rbqSdtStage = String(stage || 'idle');
        const label = {
            idle: '等待解析 tagger',
            parsing: '正在解析 tagger',
            'ready-generate': 'tagger 已返回，可生成图片',
            'generating-image': '正在生成图片',
            generated: '图片已生成',
            'done-no-draw': 'tagger 判断无需生图',
            error: '发生错误，可重试',
        }[String(stage || 'idle')] || String(stage || 'idle');
        wrapper.dataset.rbqSdtStageLabel = label;
        wrapper.title = label;
    }

    async function runImageGenerationForWrapper(wrapper, messageId, baseKey, segmentKey = '') {
        if (onSdtNaiPayload.disposed) return;
        const finalPrompt = String(wrapper?.dataset?.rbqSdtFinalPrompt || wrapper?.dataset?.prompt || '').trim();
        if (!finalPrompt || finalPrompt === '[Smart Draw]') {
            toastr.warning('当前还没有可用 prompt，请先解析 tag', PLUGIN_NAME);
            return;
        }
        try {
            setWrapperStage(wrapper, 'generating-image');
            setWrapperLoading(wrapper, 'tagger 已完成，正在调用 RBQ 生图...');
            setGenerateButtonState(wrapper, true, '生成中...', true);
            const segment = { characters: [], mangaPage: wrapper.dataset.rbqSdtManga === '1',
                mangaUseCoords: wrapper.dataset.rbqSdtMangaCoords === '1', negativePrompt: wrapper.dataset.rbqSdtNegative,
                mangaTextCompiled: wrapper.dataset.rbqSdtMangaTextCompiled === '1' };
            if (segment.mangaPage && wrapper.dataset.rbqSdtMangaRenderSettings) {
                segment.mangaRenderSettings = JSON.parse(wrapper.dataset.rbqSdtMangaRenderSettings);
            }
            const charDataJson = wrapper?.dataset?.rbqSdtCharData;
            if (charDataJson) segment.characters = JSON.parse(charDataJson);
            const image = await generateSdtImage(segment, finalPrompt, 'smart-draw-trigger', { messageId }, (progressText) => {
                const sub = wrapper.querySelector('.st-scene-trigger-nai-loader-sub');
                if (sub instanceof HTMLElement) sub.textContent = progressText;
            });
            if (onSdtNaiPayload.disposed) return;
            if (charDataJson) wrapper.dataset.rbqSdtCharData = JSON.stringify(segment.characters);
            RBQ.api.renderInlineGeneratedImage(wrapper, image);
            if (wrapper.dataset.rbqSdtExternalId) persistSdtImageCardRecord(wrapper, segment, finalPrompt, image);
            const effectiveSegKey = segmentKey || wrapper?.dataset?.rbqSdtSegmentKey || baseKey;
            if (baseKey && effectiveSegKey) markSegmentAutoGenerated(baseKey, effectiveSegKey, image, messageId);
            // Don't re-show tagger button — it lives on the bottom re-parse card only
            setGenerateButtonState(wrapper, true, getRegenLabel(wrapper), false);
            setWrapperStage(wrapper, 'generated');
        } catch (error) {
            if (onSdtNaiPayload.disposed) return;
            toastr.error(error.message || String(error), PLUGIN_NAME);
            setGenerateButtonState(wrapper, true, '🎨 生成图片', false);
            setWrapperStage(wrapper, 'error');
        } finally {
            if (!onSdtNaiPayload.disposed) clearWrapperLoading(wrapper);
        }
    }

    function bindWrapperManualRun(wrapper, trigger, messageId, baseKey, segmentKey = '') {
        if (!(wrapper instanceof HTMLElement)) return;
        if (wrapper.dataset.rbqSdtBound === '1') return;
        wrapper.dataset.rbqSdtBound = '1';
        const button = wrapper.querySelector('.st-scene-trigger-generate');
        const generateButton = ensureRenderGenerateButton(wrapper);
        if (!(button instanceof HTMLButtonElement)) return;
        button.addEventListener('click', async (event) => {
            event.preventDefault();
            event.stopPropagation();
            // If tagger is running, abort it instead of starting a new one
            if (wrapper._taggerAbort) {
                wrapper._taggerAbort.abort();
            }
            if (inFlight.has(baseKey)) return;
            inFlight.add(baseKey);
            try {
                setWrapperStage(wrapper, 'parsing');
                await runTaggerForWrapper(wrapper, trigger, messageId, baseKey);
            } finally {
                inFlight.delete(baseKey);
            }
        });
        if (generateButton instanceof HTMLButtonElement) {
            generateButton.addEventListener('click', async (event) => {
                event.preventDefault();
                event.stopPropagation();
                await runImageGenerationForWrapper(wrapper, messageId, baseKey, segmentKey || wrapper.dataset.rbqSdtSegmentKey || '');
            });
        }
    }

    /** Attach a generated external page without flattening its character/settings snapshot into the host prompt. */
    function bindSdtImageCard(wrapper, segment, prompt = getFinalPrompt(segment)) {
        if (onSdtNaiPayload.disposed) return wrapper;
        if (!(wrapper instanceof HTMLElement) || !segment || !prompt) return wrapper;
        const snapshot = JSON.parse(JSON.stringify(segment));
        snapshot.scene = prompt;
        snapshot.prompt = prompt;
        wrapper.dataset.prompt = prompt;
        wrapper.dataset.rbqSdtFinalPrompt = prompt;
        wrapper.dataset.rbqSdtIsResult = '1';
        wrapper.dataset.rbqSdtSegmentSnapshot = JSON.stringify(snapshot);
        cacheWrapperCharacterData(wrapper, snapshot);
        const hostButton = wrapper.querySelector('.st-scene-trigger-generate:not(.rbq-sdt-run-image)')
            || wrapper.querySelector('.st-scene-trigger-generate');
        if (hostButton instanceof HTMLElement) hostButton.style.setProperty('display', 'none', 'important');
        const redrawButton = setGenerateButtonState(wrapper, true, '🔄 漫画工作台', false) || ensureRenderGenerateButton(wrapper);
        if (redrawButton instanceof HTMLButtonElement && wrapper.dataset.rbqSdtExternalBound !== '1') {
            wrapper.dataset.rbqSdtExternalBound = '1';
            redrawButton.addEventListener('click', async event => {
                event.preventDefault();
                event.stopPropagation();
                // A card can outlive a plugin reload; dispatch through the installed instance.
                await RBQ.api.redrawSdtImageCard?.(wrapper);
            });
        }
        setWrapperStage(wrapper, 'generated');
        renderCardBadges(wrapper, snapshot);
        return wrapper;
    }

    function getSdtImageCardRecords(messageId) {
        const value = RBQ.api.getMessageExtra?.(messageId, 'rbq_manga_studio_images')
            || RBQ.api.getContext?.()?.chat?.[Number(messageId)]?.extra?.rbq_manga_studio_images;
        return Array.isArray(value) ? value : [];
    }

    function findSdtImageCardRecord(current) {
        const chat = RBQ.api.getContext?.()?.chat || [];
        const messageId = Number(current?.messageId);
        const records = (Number.isFinite(messageId) && current?.messageId !== null && current?.messageId !== undefined)
            ? getSdtImageCardRecords(messageId) : chat.flatMap((_message, index) => getSdtImageCardRecords(index));
        const cacheId = current?.cacheId;
        const url = current?.displayUrl || current?.url;
        const prompt = String(current?.prompt || '').trim();
        return records.find(record => record?.segment?.mangaPage && (
            cacheId ? record.image?.cacheId === cacheId : url
                ? [record.image?.url, record.image?.displayUrl, record.image?.serverUrl, record.image?.serverOriginalUrl].includes(url)
                : prompt && record.prompt === prompt));
    }

    function persistSdtImageCardRecord(wrapper, segment, prompt, image = null, initialize = false) {
        if (onSdtNaiPayload.disposed) return;
        const id = wrapper?.dataset?.rbqSdtExternalId;
        const messageId = Number(wrapper?.dataset?.messageId);
        if (!id || !Number.isFinite(messageId) || wrapper.dataset.rbqSdtExternalChat !== getChatKey()) return;
        const records = getSdtImageCardRecords(messageId);
        const previous = records.find(record => record?.id === id);
        if (!previous && !initialize) return; // A deleted/reindexed message no longer owns this card.
        const snapshot = JSON.parse(JSON.stringify(segment));
        snapshot.scene = prompt; snapshot.prompt = prompt;
        const record = { ...previous, id, prompt, segment: snapshot, image: image ? JSON.parse(JSON.stringify(image)) : previous?.image,
            createdAt: previous?.createdAt || Date.now() };
        const next = records.filter(item => item?.id !== id).concat(record);
        wrapper.dataset.rbqSdtSegmentSnapshot = JSON.stringify(snapshot);
        if (typeof RBQ.api.setMessageExtra === 'function') RBQ.api.setMessageExtra(messageId, 'rbq_manga_studio_images', next);
        else {
            const message = RBQ.api.getContext?.()?.chat?.[messageId];
            if (message) {
                (message.extra ||= {}).rbq_manga_studio_images = next;
                RBQ.api.saveChatDebounced?.();
            }
        }
    }

    function createSdtImageCard({ messageId, segment, prompt = getFinalPrompt(segment), image, id = `manga-studio:${Date.now()}:${Math.random().toString(36).slice(2)}`, persist = true }) {
        if (onSdtNaiPayload.disposed) return null;
        const container = RBQ.api.getMessageTextContainer?.(messageId);
        if (!(container instanceof HTMLElement) || !segment?.mangaPage || !prompt) return null;
        const wrapper = RBQ.api.createPromptCard({ messageId, prompt, id, label: 'manga-studio' });
        if (!(wrapper instanceof HTMLElement)) return null;
        wrapper.dataset.rbqSdtExternalId = id;
        wrapper.dataset.rbqSdtExternalChat = getChatKey();
        // External pages have their own saved records; host history and ordinary SDT cache must not replace them.
        wrapper.dataset.rbqSdtKey = id;
        bindSdtImageCard(wrapper, segment, prompt);
        container.append(wrapper);
        if (image) {
            RBQ.api.renderInlineGeneratedImage(wrapper, image);
            renderCardBadges(wrapper, JSON.parse(wrapper.dataset.rbqSdtSegmentSnapshot));
        }
        if (persist) persistSdtImageCardRecord(wrapper, segment, prompt, image, true);
        return wrapper;
    }

    async function restoreSdtImageCards(messageId) {
        if (onSdtNaiPayload.disposed) return;
        const records = getSdtImageCardRecords(messageId);
        const container = RBQ.api.getMessageTextContainer?.(messageId);
        if (!(container instanceof HTMLElement) || !records.length) return;
        const chatKey = getChatKey();
        for (const record of records) {
            if (!record?.id || !record.segment?.mangaPage || !record.prompt || !record.image) continue;
            const existing = [...container.querySelectorAll('[data-rbq-sdt-external-id]')].find(card => card.dataset.rbqSdtExternalId === record.id);
            if (existing) {
                if (existing.dataset.rbqSdtExternalBound !== '1') bindSdtImageCard(existing, record.segment, record.prompt);
                else {
                    let snapshot = record.segment;
                    try { snapshot = JSON.parse(existing.dataset.rbqSdtSegmentSnapshot || 'null') || snapshot; } catch (_) {}
                    renderCardBadges(existing, snapshot);
                }
                continue;
            }
            // Mount before resolving the cached image URL, so overlapping scans cannot duplicate this card.
            const wrapper = createSdtImageCard({ messageId, ...record, image: null, persist: false });
            if (!wrapper) continue;
            let image = { ...record.image };
            if (image.cacheId && typeof RBQ.api.ensureHistoryItemDisplayUrl === 'function') {
                const url = await RBQ.api.ensureHistoryItemDisplayUrl(image).catch(() => '');
                if (url) image.url = url;
            }
            if (onSdtNaiPayload.disposed) return;
            if (getChatKey() !== chatKey || !wrapper.isConnected) continue;
            RBQ.api.renderInlineGeneratedImage(wrapper, image);
            renderCardBadges(wrapper, JSON.parse(wrapper.dataset.rbqSdtSegmentSnapshot));
        }
    }

    async function maybeAutoGenerate(wrapper, result, messageId, baseKey, segmentKey) {
        const store = getStore();
        const effectiveSegKey = segmentKey || wrapper?.dataset?.rbqSdtSegmentKey || baseKey;
        const state = getSegmentState(store, baseKey, effectiveSegKey, messageId);

        // 🛡️ 核心防御：若未开启自动生图、或已经自动生成过、或已有有效图片结果，绝对不再自动生图
        if (!store.autoRunGenerate) return;
        if (state?.autoGenerated || (state?.imageResult && (state.imageResult.url || state.imageResult.cacheId || state.imageResult.serverUrl))) {
            return;
        }

        // 🛡️ DOM防御：若当前卡片已经有图片渲染，或处于 generated 状态，绝对不再重复生图
        if (wrapper instanceof HTMLElement) {
            const hasExistingImg = !!wrapper.querySelector('.st-scene-trigger-inline-result img, .st-scene-trigger-inline-result video') ||
                                   wrapper.dataset.rbqSdtStage === 'generated' ||
                                   !!wrapper.dataset.latestImageUrl;
            if (hasExistingImg) return;
        }

        try {
            setWrapperStage(wrapper, 'generating-image');
            setWrapperLoading(wrapper, 'tagger 已返回，正在调用 RBQ 生图...');
            setGenerateButtonState(wrapper, true, '自动生成中...', true);

            const finalPrompt = getFinalPrompt(result);
            if (!finalPrompt || finalPrompt === '[Smart Draw]') {
                console.warn(`[${PLUGIN_NAME}] Auto-generate skipped: empty or placeholder prompt`, result);
                return;
            }
            const image = await generateSdtImage(result, finalPrompt, 'smart-draw-trigger', { messageId }, (progressText) => {
                const sub = wrapper.querySelector('.st-scene-trigger-nai-loader-sub');
                if (sub instanceof HTMLElement) sub.textContent = progressText;
            });
            cacheWrapperCharacterData(wrapper, result);
            RBQ.api.renderInlineGeneratedImage(wrapper, image);
            markSegmentAutoGenerated(baseKey, effectiveSegKey, image, messageId);
            setGenerateButtonState(wrapper, true, getRegenLabel(wrapper), false);
            setWrapperStage(wrapper, 'generated');
        } catch (error) {
            toastr.error(error.message || String(error), PLUGIN_NAME);
            setGenerateButtonState(wrapper, true, getRegenLabel(wrapper), false);
            setWrapperStage(wrapper, 'error');
        } finally {
            clearWrapperLoading(wrapper);
        }
    }

    async function runTaggerForWrapper(wrapper, trigger, messageId, key) {
        const store = getStore();
        if (!(wrapper instanceof HTMLElement)) return;
        const origin = captureMangaRequestContext(null, messageId);
        const abortController = new AbortController();
        wrapper._taggerAbort = abortController;
        wrapper.querySelector('.rbq-sdt-debug-box')?.remove();
        wrapper.querySelector('.rbq-sdt-debug-toggle-btn')?.remove();
        setWrapperStage(wrapper, 'parsing');
        const button = ensureTaggerButtonState(wrapper, '解析中... (点击停止)');
        if (button) button.disabled = false;
        try {
            const sub = wrapper.querySelector('.st-scene-trigger-nai-loader-sub');
            const loader = wrapper.querySelector('.st-scene-trigger-inline-loader');
            if (loader instanceof HTMLElement) loader.style.display = 'flex';
            let result;
            try {
                result = await callTagger(messageId, trigger, { signal: abortController.signal });
            } catch (err) {
                if (key !== 'diagnostic' && err && (err.code === 'MANGA_BUBBLE_OWNERSHIP' || err.code === 'MANGA_BUBBLE_SPEAKER') && err.rawOutput) {
                    console.warn(`[${PLUGIN_NAME}] 漫画气泡归属未完全匹配，启动零阻断自愈容错`, err);
                    try {
                        let rawObj = typeof err.rawOutput === 'string' ? JSON.parse(err.rawOutput) : err.rawOutput;
                        rawObj = autoHealMangaTaggerPayload(rawObj);
                        result = validateStructuredResult(normalizeTaggerResult(rawObj, [], captureMangaRequestContext(null, messageId)));
                        if (typeof toastr !== 'undefined' && toastr.info) {
                            toastr.info('部分画格对白未标明说话者，已自动自愈归入角色，生图继续进行', PLUGIN_NAME);
                        }
                    } catch (healErr) {
                        console.error(`[${PLUGIN_NAME}] 自愈失败，进入原始报错流程:`, healErr);
                        throw err;
                    }
                } else {
                    throw err;
                }
            }
            const cacheKey = wrapper.dataset.rbqSdtBaseKey || key;
            const sanitized = sanitizeSdtResult(result);
            const currentMes = getMessageSnapshot(messageId);
            const currentMesHash = hashText(currentMes?.mes || '');
            const cacheEntry = {
                ...sanitized,
                checked: true,
                createdAt: Date.now(),
                triggerType: trigger.type,
                marker: trigger.marker || '',
                mesHash: currentMesHash,
                segmentStates: {},  // Fresh states — re-parse means new tags, old images don't apply
                key: cacheKey,
            };
            store.cache[cacheKey] = cacheEntry;
            pruneCache();
            save();

            // === Sync to message.extra.rbq_sdt (chat-level persistence, cross-device sync) ===
            saveMsgExtraSdt(messageId, cacheEntry);
            // One toast per global import of this fresh parse, with 「撤销」 (never on reload / cache restore).
            try { notifyGlobalImports(messageId, cacheKey, cacheEntry); } catch (e) { console.warn(`[${PLUGIN_NAME}] global import toast failed`, e); }

            const hasUsableSegments = Array.isArray(result?.segments) && result.segments.some((segment) => getFinalPrompt(segment) || segment.scene || (segment.characters && segment.characters.length > 0));
            const hasTopLevelPrompt = !!getFinalPrompt(result) || !!result?.scene;
            if (!result.shouldDraw && !hasUsableSegments && !hasTopLevelPrompt) {
                if (store.cardPosition === 'message_actions') {
                    if (wrapper.parentElement) wrapper.remove();
                    toastr.info('tagger 判定无需生图', PLUGIN_NAME);
                } else {
                    ensureTaggerButtonState(wrapper, '⚠️ tagger 判定无需生图（点击重新解析）');
                    setGenerateButtonState(wrapper, false);
                    setWrapperStage(wrapper, 'done-no-draw');
                    renderTaggerDebugInfo(wrapper, result);
                }
                syncMessageActionButton(messageId, null, trigger, cacheKey);
                processedKeys.add(cacheKey);
                return;
            }
            // Remove old segment cards before re-materializing — prevents stale cards
            // lingering when re-parse returns different segments or fewer segments.
            const container = RBQ.api.getMessageTextContainer(messageId);
            if (container instanceof HTMLElement) {
                const oldCards = container.querySelectorAll(`.${CARD_CLASS}[data-rbq-sdt-is-result="1"]`);
                console.info(`[Smart Draw] 🧹 re-parse cleanup: found ${oldCards.length} old cards to remove`, {
                    messageId,
                    cacheKey,
                    allSdtCards: container.querySelectorAll(`.${CARD_CLASS}`).length,
                });
                oldCards.forEach(card => card.remove());
            }
            const rendered = materializeResultCards(messageId, trigger, result, cacheKey);
            // Repurpose the initial placeholder card as the sole "re-parse" button at bottom
            if (store.cardPosition !== 'message_actions' && rendered.length > 0 && rendered.every(item => item.wrapper !== wrapper)) {
                wrapper.classList.add('rbq-sdt-reparse');
                wrapper.dataset.rbqSdtIsResult = '0';
                const resEl = wrapper.querySelector('.st-scene-trigger-inline-result');
                if (resEl) { resEl.innerHTML = ''; resEl.classList.remove('is-visible'); }
                ensureTaggerButtonState(wrapper, '🔄 重新解析/刷新 tag');
                setGenerateButtonState(wrapper, false);
                setWrapperStage(wrapper, 'ready-generate');
                clearWrapperLoading(wrapper);
            } else if (store.cardPosition === 'message_actions') {
                if (wrapper.parentElement) wrapper.remove();
            }
            syncMessageActionButton(messageId, null, trigger, cacheKey);
            for (const item of rendered) {
                const renderedWrapper = item.wrapper;
                // 重新解析/主动解析完成：新分镜必须基于最新提示词与标签，严禁复用旧图
                if (store.autoRunGenerate) {
                    await maybeAutoGenerate(renderedWrapper, item.segment, messageId, cacheKey, item.key);
                } else {
                    const segLabel = getSegmentLabel(item.segment);
                    setGenerateButtonState(renderedWrapper, true, segLabel, false);
                    setWrapperStage(renderedWrapper, 'ready-generate');
                }
            }
            processedKeys.add(cacheKey);
        } catch (error) {
            if (error.name === 'AbortError') {
                console.info(`[${PLUGIN_NAME}] tagger 解析已被用户停止`);
                toastr.warning('解析已停止', PLUGIN_NAME);
                ensureTaggerButtonState(wrapper, '📷 开始解析/生成 tag');
                setGenerateButtonState(wrapper, false);
                setWrapperStage(wrapper, 'idle');
            } else {
                console.error('[Smart Draw Trigger]', error);
                toastr.error(error.message || String(error), PLUGIN_NAME);
                ensureTaggerButtonState(wrapper, '⚠️ 解析失败（点击重试）');
                setGenerateButtonState(wrapper, false);
                setWrapperStage(wrapper, 'error');
                let formattedDebugTrace = `【错误信息】: ${error.message || String(error)}\n`;
                if (error.debugInfo) {
                    formattedDebugTrace += `【拦截状态】: ${error.debugInfo.reason || '请求或解析失败'}\n`;
                    formattedDebugTrace += `【目标模型】: ${error.debugInfo.model || '未知'}\n`;
                    if (error.debugInfo.llmOutput) {
                        formattedDebugTrace += `【大模型原始正文】: ${error.debugInfo.llmOutput}\n`;
                    }
                    if (Array.isArray(error.debugInfo.chunks) && error.debugInfo.chunks.length > 0) {
                        formattedDebugTrace += `\n【服务端原始响应报文 (Raw Chunks)】:\n${JSON.stringify(error.debugInfo.chunks, null, 2)}\n`;
                    }
                }
                // Response validation can fail after receiving complete model output.
                // Preserve that trace alongside transport diagnostics for inspection.
                if (Array.isArray(error.validationIssues) && error.validationIssues.length) {
                    formattedDebugTrace += `\n【完整字段校验问题】:\n${error.validationIssues.join('\n')}\n`;
                }
                if (error.rawOutput) {
                    const rawOutput = typeof error.rawOutput === 'string' ? error.rawOutput : JSON.stringify(error.rawOutput, null, 2);
                    formattedDebugTrace += `\n【原始输出 (Raw Output)】:\n${rawOutput}\n`;
                } else if (!error.debugInfo) {
                    formattedDebugTrace += '\n【说明】: 未记录原始输出；请检查接口配置或调试日志。\n';
                }
                formattedDebugTrace += `\n【JavaScript 异常调用栈 (Stack Trace)】:\n${error.stack || ''}`;

                renderTaggerDebugInfo(wrapper, {
                    isError: true,
                    shouldDraw: false,
                    reason: error.message || String(error),
                    errorCode: error.code || '',
                    errorCategory: getTaggerErrorCategory({ reason: error.message || String(error),
                        errorCode: error.code || '', rawOutput: error.rawOutput || '' }),
                    rawOutput: formattedDebugTrace
                });
            }
        } finally {
            delete wrapper._taggerAbort;
            clearWrapperLoading(wrapper);
        }
    }

    let lastChatKey = null;

    async function processMessage(messageId, options = {}) {
        if (onSdtNaiPayload.disposed) return;
        const { allowHistorical = false, force = false } = options;
        const id = Number(messageId);
        if (!Number.isFinite(id)) return;
        await restoreSdtImageCards(id);
        if (onSdtNaiPayload.disposed) return;
        // 关键流式守卫：无论是否 force，只要该楼层正在流式输出或处于「思考中......」，严禁介入！
        if (isMessageCurrentlyStreaming(id)) {
            debugInfo(`⏳ skipping processMessage for #${id} — streaming / thinking is active`);
            return;
        }
        const store = getStore();

        // Auto-refresh profile UI & sync chat context when it becomes available or changes
        const currentChatKey = getChatKey();
        if (currentChatKey && currentChatKey !== '_global' && currentChatKey !== lastChatKey) {
            const isInitialTransition = (lastChatKey === null || lastChatKey === '_global');
            console.info(`[Smart Draw] 🔄 chat context resolved: ${lastChatKey} -> ${currentChatKey}`);
            lastChatKey = currentChatKey;
            refreshCharacterProfileListUi();
            // 关键修复：绝不可在单条消息的 processMessage 中盲目执行全文档 document.querySelectorAll('.rbq-sdt-card').forEach(el => el.remove())！
            // 否则会瞬间清空已挂载的其他所有楼层的生图卡片与按钮，且不会重新触发扫描，导致按钮凭空消失！
            // 只有当 chat 确实发生实际切换（非首次加载）时，才调度安全全量扫描
            if (!isInitialTransition) {
                processedKeys.clear();
                document.querySelectorAll(`.${CARD_CLASS}`).forEach(el => { el._taggerAbort?.abort(); el.remove(); });
                setTimeout(() => scanAllVisible(true), 100);
            }
        }

        const message = getMessageSnapshot(id);
        if (!shouldHandleMessage(message, id)) return;
        const trigger = getTrigger(message);
        if (!trigger) return;
        const key = makeKey(id, message, trigger.type, trigger.marker || 'auto');
        const currentMesHash = hashText(message?.mes || '');
        if (force) processedKeys.delete(key);
        const container = RBQ.api.getMessageTextContainer(id);
        if (!(container instanceof HTMLElement)) {
            // DOM 容器尚未挂载（如酒馆正在异步渲染历史楼层），延迟 200ms 重试，严禁提前 mark processedKeys
            setTimeout(() => scheduleProcess(id, options), 200);
            return;
        }
        const removedStaleCards = removeStaleCards(container, key);
        if (removedStaleCards > 0) {
            debugInfo(`🧹 removed ${removedStaleCards} stale card(s) for message ${id}`, { key });
        }
        // If any card in this message is currently being parsed, don't create new cards
        const activeParsingCard = container.querySelector(`.${CARD_CLASS}[data-rbq-sdt-stage="parsing"]`);
        if (activeParsingCard) {
            debugInfo(`⏳ skipping processMessage for #${id} — tagger is active`);
            return;
        }
        const hasCurrentCards = hasCardsForBaseKey(container, key);
        if (processedKeys.has(key) && !force) {
            if (hasCurrentCards) return;
            processedKeys.delete(key);
            debugInfo(`♻️ cards missing for processed key, restoring from cache`, { messageId: id, key });
        }
        if (hasCurrentCards && !force) {
            processedKeys.add(key);
            return;
        }
        if (processedKeys.has(key)) return;
        if (inFlight.has(key)) return;

        const extraSdt = getMsgExtraSdt(id);
        // 关键防护：只有当 extraSdt 中的文本 hash 或 key 与当前消息正文完全一致时，才认定为有效缓存
        // 若用户点击了重新生成 (Regenerate / Swipe)，正文已变更，旧楼层/旧版本的 extraSdt 绝不可错挂到新生成中！
        const isExtraValid = !!(extraSdt && (
            extraSdt.key === key ||
            (extraSdt.mesHash && extraSdt.mesHash === currentMesHash) ||
            (typeof extraSdt.key === 'string' && extraSdt.key.includes(`:${currentMesHash}:`))
        ));
        const cached = (isExtraValid ? extraSdt : null) || store.cache[key];
        if (cached?.checked && !cached.shouldDraw) {
            if (store.cardPosition === 'message_actions') {
                if (container instanceof HTMLElement) {
                    container.querySelectorAll(`.${CARD_CLASS}[data-rbq-sdt-is-result="0"], .${CARD_CLASS}.rbq-sdt-reparse`).forEach(c => c.remove());
                }
                syncMessageActionButton(messageId, null, trigger, key);
                processedKeys.add(key);
                return;
            }
            // 如果缓存中判定为“无需生图”，依然渲染一个可重新解析的卡片，防止按钮凭空消失导致用户无法手动生图
            const noDrawPlaceholder = {
                shouldDraw: false,
                prompt: '',
                negative: '',
                anchor: { type: 'bottom' },
                reason: cached.reason || 'tagger 判断无需生图',
                rawOutput: cached.rawOutput || '',
                thinkContent: cached.thinkContent || '',
                multiChar: false,
                scene: '',
                characters: [],
            };
            insertCard(messageId, trigger, noDrawPlaceholder, key, key, (wrapper) => {
                ensureTaggerButtonState(wrapper, '⚠️ tagger 判定无需生图（点击重新解析）');
                setGenerateButtonState(wrapper, false);
                setWrapperStage(wrapper, 'done-no-draw');
                bindWrapperManualRun(wrapper, trigger, messageId, key);
                renderTaggerDebugInfo(wrapper, noDrawPlaceholder);
                const loader = wrapper.querySelector('.st-scene-trigger-inline-loader');
                if (loader instanceof HTMLElement) loader.style.display = 'none';
            });
            processedKeys.add(key);
            return;
        }
        if (cached?.shouldDraw && (cached.prompt || cached.segments?.length)) {
            const rendered = materializeResultCards(messageId, trigger, cached, key);
            for (const item of rendered) {
                const wrapper = item.wrapper;
                const segmentState = getSegmentState(store, key, item.key, messageId);
                let restoredResult = segmentState.imageResult ? { ...segmentState.imageResult } : null;

                // 多端跨设备容灾兜底：若 SDT 本地分镜状态未包含有效图片，从宿主图库历史拉取
                if (!restoredResult || (!restoredResult.url && !restoredResult.cacheId && !restoredResult.serverUrl)) {
                    if (typeof RBQ?.api?.getLatestHistoryItemForScope === 'function') {
                        const hostItem = RBQ.api.getLatestHistoryItemForScope({
                            messageId,
                            prompt: item.segment?.prompt || ''
                        });
                        if (hostItem && (hostItem.cacheId || hostItem.url || hostItem.serverUrl || hostItem.serverPreviewUrl || hostItem.serverOriginalUrl)) {
                            restoredResult = { ...hostItem };
                        }
                    }
                }

                if (restoredResult && (restoredResult.cacheId || restoredResult.url || restoredResult.serverUrl || restoredResult.serverPreviewUrl || restoredResult.serverOriginalUrl)) {
                    // Restore valid display URL from IndexedDB or Server via cacheId/serverUrl
                    debugInfo(`🔄 restoring image for ${item.key}`, {
                        cacheId: restoredResult.cacheId || '(none)',
                        storedUrl: restoredResult.url?.substring(0, 60),
                        apiAvailable: typeof RBQ.api.ensureHistoryItemDisplayUrl === 'function',
                    });
                    if (typeof RBQ.api.ensureHistoryItemDisplayUrl === 'function') {
                        try {
                            const freshUrl = await RBQ.api.ensureHistoryItemDisplayUrl(restoredResult);
                            debugInfo(`✅ restored URL from IndexedDB/Server: ${freshUrl?.substring(0, 60)}`);
                            if (freshUrl) restoredResult.url = freshUrl;
                        } catch (e) {
                            console.warn(`[Smart Draw] ❌ ensureHistoryItemDisplayUrl failed:`, e);
                        }
                    }
                    // 过滤旧会话中已失效的 blob: URL，避免将刷新前无效的内存 blob 当作有效图片进行渲染
                    const isBlobActive = restoredResult.url && restoredResult.url.startsWith('blob:') && (typeof RBQ?.api?.isCachedObjectUrlActive === 'function' ? RBQ.api.isCachedObjectUrlActive(restoredResult.url) : true);
                    const finalUrl = restoredResult.serverPreviewUrl
                        || (restoredResult.url && !restoredResult.url.startsWith('blob:') && restoredResult.url.includes('_preview.webp') ? restoredResult.url : '')
                        || (restoredResult.url && !restoredResult.url.startsWith('blob:') ? restoredResult.url : '')
                        || (isBlobActive ? restoredResult.url : '')
                        || restoredResult.serverUrl
                        || restoredResult.serverOriginalUrl;

                    if (finalUrl) {
                        restoredResult.url = finalUrl;
                        RBQ.api.renderInlineGeneratedImage(wrapper, restoredResult);
                        setGenerateButtonState(wrapper, true, getRegenLabel(wrapper), false);
                        setWrapperStage(wrapper, 'generated');
                    } else {
                        // 图像恢复失败（如 blob 已过期且无服务端/IndexedDB 缓存）：坚决回退为就绪生图状态，确保生图按钮绝不消失！
                        const segLabel = getSegmentLabel(item.segment);
                        setGenerateButtonState(wrapper, true, segLabel, false);
                        setWrapperStage(wrapper, 'ready-generate');
                    }
                } else {
                    // 历史楼层/未出图分镜：仅重置按钮文案为分镜标签并保持就绪，绝不可在历史扫描/页面刷新时自动发起网络生图请求
                    const segLabel = getSegmentLabel(item.segment);
                    setGenerateButtonState(wrapper, true, segLabel, false);
                    setWrapperStage(wrapper, 'ready-generate');
                }
            }
            // Insert a bottom re-parse card if segments were rendered (仅在非 message_actions 模式挂载正文重新解析按钮)
            if (rendered.length > 0 && store.cardPosition !== 'message_actions') {
                const reparseKey = `${key}-reparse`;
                const reparsePlaceholder = {
                    shouldDraw: true, prompt: '', negative: '',
                    anchor: { type: 'bottom' }, reason: '', multiChar: false,
                    scene: '', characters: [],
                };
                insertCard(messageId, trigger, reparsePlaceholder, reparseKey, key, (reparseWrapper) => {
                    reparseWrapper.classList.add('rbq-sdt-reparse');
                    reparseWrapper.dataset.rbqSdtIsResult = '0';
                    const resEl = reparseWrapper.querySelector('.st-scene-trigger-inline-result');
                    if (resEl) { resEl.innerHTML = ''; resEl.classList.remove('is-visible'); }
                    ensureTaggerButtonState(reparseWrapper, '🔄 重新解析/刷新 tag');
                    setGenerateButtonState(reparseWrapper, false);
                    setWrapperStage(reparseWrapper, 'ready-generate');
                    bindWrapperManualRun(reparseWrapper, trigger, messageId, key);
                });
            } else if (store.cardPosition === 'message_actions') {
                syncMessageActionButton(messageId, null, trigger, key);
            }
            processedKeys.add(key);
            return;
        }

        // 若用户选择了「消息操作栏小图标」纯净模式，在未解析前绝不在正文插入占位大卡片与按钮
        if (store.cardPosition === 'message_actions') {
            if (container instanceof HTMLElement) {
                container.querySelectorAll(`.${CARD_CLASS}[data-rbq-sdt-is-result="0"], .${CARD_CLASS}.rbq-sdt-reparse`).forEach(c => c.remove());
            }
            syncMessageActionButton(messageId, null, trigger, key);
            processedKeys.add(key);
            return;
        }

        const initialPlaceholder = {
            shouldDraw: true,
            prompt: '',
            negative: '',
            anchor: { type: 'bottom' },
            reason: '',
            multiChar: false,
            scene: '',
            characters: [],
        };
        insertCard(messageId, trigger, initialPlaceholder, key, key, (wrapper) => {
            ensureTaggerButtonState(wrapper, '📷 开始解析/生成 tag');
            setGenerateButtonState(wrapper, false);
            setWrapperStage(wrapper, 'idle');
            bindWrapperManualRun(wrapper, trigger, messageId, key);
            const loader = wrapper.querySelector('.st-scene-trigger-inline-loader');
            if (loader instanceof HTMLElement) loader.style.display = 'none';
        });
        // Auto-run is driven by the streaming watcher (triggerAutoRunForLatest),
        // NOT here. processMessage only creates/restores cards.
    }

    function scheduleProcess(messageId, options = {}) {
        if (onSdtNaiPayload.disposed) return;
        const id = Number(messageId);
        if (!Number.isFinite(id)) return;
        // 如果当前消息正在流式生成或在思考中，严禁提前介入渲染与解析，静待流式结束后由 startStreamingWatcher 统一调度
        if (isMessageCurrentlyStreaming(id)) return;
        clearTimeout(pendingTimers.get(id));

        // 优化切换分身/滑动时的生图还原体验：如果该版本文本已有缓存结果，则直接以 16ms 超低延迟立刻渲染，实现无感秒出。
        // 如果没有缓存，则保持 400ms 的防抖延迟，敏捷响应打字与流式。
        const store = getStore();
        const message = getMessageSnapshot(id);
        const trigger = getTrigger(message);
        let delay = options.force ? 16 : 400;
        if (trigger) {
            const key = makeKey(id, message, trigger.type, trigger.marker || 'auto');
            const currentMesHash = hashText(message?.mes || '');
            const extraSdt = getMsgExtraSdt(id);
            const isExtraValid = !!(extraSdt && (
                extraSdt.key === key ||
                (extraSdt.mesHash && extraSdt.mesHash === currentMesHash) ||
                (typeof extraSdt.key === 'string' && extraSdt.key.includes(`:${currentMesHash}:`))
            ));
            if (isExtraValid || store.cache[key]) {
                delay = 16;
            }
        }

        pendingTimers.set(id, setTimeout(() => {
            pendingTimers.delete(id);
            processMessage(id, options);
        }, delay));
    }

    function syncCardPositionsOnSettingChange() {
        const store = getStore();
        const pos = store.cardPosition || 'bottom';
        document.querySelectorAll('.mes[mesid]').forEach(mesEl => {
            const id = Number(mesEl.getAttribute('mesid'));
            if (!Number.isFinite(id)) return;
            const container = RBQ.api.getMessageTextContainer(id);
            if (!(container instanceof HTMLElement)) return;

            // 1. 同步消息操作栏小图标 (非 message_actions 模式绝不残留)
            const btnBar = mesEl.querySelector('.extraMesButtons') || mesEl.querySelector('.mes_buttons') || mesEl.querySelector('.flex-container');
            const actionBtn = btnBar?.querySelector('.rbq-sdt-action-btn');
            if (pos !== 'message_actions') {
                if (actionBtn) actionBtn.remove();
            }

            // 2. 正文占位卡片 (data-rbq-sdt-is-result="0") 与重新解析卡片 (.rbq-sdt-reparse)
            const unresultCards = Array.from(container.querySelectorAll(`.${CARD_CLASS}[data-rbq-sdt-is-result="0"], .${CARD_CLASS}.rbq-sdt-reparse`));
            if (pos === 'message_actions') {
                unresultCards.forEach(c => c.remove());
                const msg = getMessageSnapshot(id);
                const trigger = getTrigger(msg);
                if (trigger) {
                    const key = makeKey(id, msg, trigger.type, trigger.marker || 'auto');
                    syncMessageActionButton(id, null, trigger, key);
                }
            } else if (unresultCards.length > 0) {
                unresultCards.forEach(card => {
                    if (pos === 'top') {
                        const reasoningEl = container.querySelector('.mes_reasoning, details, .thinking-block, .thought');
                        if (reasoningEl && reasoningEl.nextSibling) {
                            container.insertBefore(card, reasoningEl.nextSibling);
                        } else if (reasoningEl) {
                            reasoningEl.insertAdjacentElement('afterend', card);
                        } else {
                            container.prepend(card);
                        }
                    } else {
                        container.append(card);
                    }
                });
            } else {
                // 原先在 message_actions 纯净模式下未出图的楼层，切换到 top/bottom 时重新挂载占位大卡片
                const hasResultCards = !!container.querySelector(`.${CARD_CLASS}[data-rbq-sdt-is-result="1"]`);
                if (!hasResultCards) {
                    scheduleProcess(id, { force: true, allowHistorical: true });
                }
            }
        });
    }

    function scanAllVisible(force = false) {
        if (onSdtNaiPayload.disposed) return;
        document.querySelectorAll('.mes[mesid]').forEach(element => {
            scheduleProcess(Number(element.getAttribute('mesid')), { allowHistorical: true, force: !!force });
        });
        // Chat context is likely loaded by now. Refresh the profile list UI if the panel is open.
        refreshCharacterProfileListUi();
    }

    function scanLatestVisible() {
        if (onSdtNaiPayload.disposed) return;
        const latest = getLatestMessageId();
        if (latest != null) scheduleProcess(latest, { force: true, allowHistorical: true });
    }

